INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c19992cc-9d68-4cb3-a0f2-7f693858986f', '6ac63f7e-f6d6-40bd-b6ef-78411d638f1b', 0, 'These are a distinct code family specifically for counseling/risk-factor-reduction intervention (not tied to a comprehensive preventive physical exam), which may be reported separately from, or in some cases in conjunction with, a preventive medicine visit depending on what was actually performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5448687c-ac9d-48db-9985-8df13461ac3c', '6ac63f7e-f6d6-40bd-b6ef-78411d638f1b', 1, 'Preventive counseling codes are identical to and interchangeable with the comprehensive preventive medicine E/M visit codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dec9a009-b418-454c-8cbb-b1f4b2d3d0af', '6ac63f7e-f6d6-40bd-b6ef-78411d638f1b', 2, 'Preventive counseling has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b8059e9a-02b7-429b-9bde-dda46367844a', '6ac63f7e-f6d6-40bd-b6ef-78411d638f1b', 3, 'Preventive counseling codes apply only to substance use topics, never diet/exercise/injury prevention topics');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('42a35d16-f85a-472a-97d3-a3f102939ea1', '17dad97c-d80f-416b-8675-1ac3a7ae2e10', 0, 'Individual and group preventive counseling have distinct codes reflecting the different service structure (one-on-one vs. group format), consistent with the general service-structure-affects-code-selection theme already established for other group-versus-individual scenarios (group medical visits, group physical therapy)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3a5be9a6-b04a-4f92-9871-c4f83511fb8d', '17dad97c-d80f-416b-8675-1ac3a7ae2e10', 1, 'Individual and group preventive counseling are coded identically regardless of format');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3ba91431-ba14-4a08-a360-150ee60d9e16', '17dad97c-d80f-416b-8675-1ac3a7ae2e10', 2, 'Group preventive counseling has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('701f26a5-6c42-4ab9-b279-ac3346a3c775', '17dad97c-d80f-416b-8675-1ac3a7ae2e10', 3, 'The choice between individual and group counseling codes depends solely on the specific risk factor being addressed, not the actual format used');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a17b9178-c2f9-4260-9829-68d07ad4e80d', '6f549910-cdb9-46f5-bc01-7477137b868c', 0, 'The IPPE (a one-time, first-year-of-Medicare-enrollment benefit) has its own specific code, distinct from the Annual Wellness Visit codes (which recur annually and have their own initial-versus-subsequent structure), reflecting genuinely different Medicare preventive benefit categories with different eligibility windows/frequency rules');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4bce0614-d31e-4b6a-ae6b-b3da3a306c15', '6f549910-cdb9-46f5-bc01-7477137b868c', 1, 'IPPE and Annual Wellness Visit are coded identically since both are Medicare preventive benefits');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4806b959-411d-4740-bc05-e0cc82e6bfec', '6f549910-cdb9-46f5-bc01-7477137b868c', 2, 'IPPE has no distinct CPT/HCPCS code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2b5acce3-0a60-4667-890c-8721299f03d3', '6f549910-cdb9-46f5-bc01-7477137b868c', 3, 'IPPE may be performed and billed multiple times per year for the same beneficiary with no frequency limitation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b883272c-99c3-464a-9e6e-6e9e7f785bee', '07829dcd-882c-4a1d-afd5-47fc25e72f9f', 0, 'Smoking cessation counseling has its own specific code(s), often time-based and tiered (e.g., intermediate vs. intensive counseling), reflecting this as its own defined, clinically significant counseling service distinct from the broader general preventive counseling code family');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('92160f58-05a0-4990-8093-61b24b3bd51a', '07829dcd-882c-4a1d-afd5-47fc25e72f9f', 1, 'Smoking cessation counseling is coded identically to general preventive counseling with no distinct code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e71aba57-14e9-43db-86fe-f2e5d340d4da', '07829dcd-882c-4a1d-afd5-47fc25e72f9f', 2, 'Smoking cessation counseling has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('008d125f-2057-4d18-9e5d-48a908284d2b', '07829dcd-882c-4a1d-afd5-47fc25e72f9f', 3, 'Smoking cessation counseling coding depends solely on the number of cigarettes smoked per day, not counseling time/intensity');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4e2d6eee-f2d8-4c65-87ba-8f46c3a6cee5', 'b890e179-0b88-4edc-9638-788e19b727cf', 0, 'SBIRT has its own specific code(s) reflecting this defined screening-plus-brief-intervention service structure, distinct from both a standard substance use disorder diagnostic evaluation and general preventive counseling, reflecting its own specific, evidence-based service model');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9360e70a-cf65-4c78-a30d-6adcefb5ad21', 'b890e179-0b88-4edc-9638-788e19b727cf', 1, 'SBIRT is coded identically to a standard psychiatric diagnostic evaluation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5956d976-9957-4f52-bc4a-6f2dd5895cb9', 'b890e179-0b88-4edc-9638-788e19b727cf', 2, 'SBIRT has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ea0741e5-e857-4a0f-b9a0-d88686e2e637', 'b890e179-0b88-4edc-9638-788e19b727cf', 3, 'SBIRT coding depends solely on the screening tool''s numeric score, not the actual service structure/time');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a6b60ec1-4c21-4357-9333-183145c1ccfe', 'a65f7d2a-48db-4517-98d3-18ee504436fe', 0, 'This has its own specific code/benefit structure reflecting a defined, evidence-based intensive behavioral counseling protocol for obesity, distinct from general preventive counseling codes and from a routine office visit addressing weight incidentally');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('24926fb5-18f1-4496-b494-fe88c0d06267', 'a65f7d2a-48db-4517-98d3-18ee504436fe', 1, 'Obesity counseling is coded identically to general preventive counseling regardless of whether it follows the specific defined intensive behavioral therapy protocol');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e8920c87-3d57-4bdb-be50-2e49c4b7f81b', 'a65f7d2a-48db-4517-98d3-18ee504436fe', 2, 'Obesity screening/counseling has no distinct CPT/HCPCS code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5ad78c06-94e8-432c-8d42-90be49744c18', 'a65f7d2a-48db-4517-98d3-18ee504436fe', 3, 'Obesity counseling coding depends solely on the patient''s BMI value, not the actual counseling service/protocol structure');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('371750e2-2564-4262-8721-b6dc19cd3280', 'c3c10b95-b4c5-4f09-b1c2-75875d3665f4', 0, 'Documentation should specify the actual time spent on the specific counseling intervention and the specific protocol/content covered, consistent with the recurring time/content-documentation-specificity theme already established throughout this content for other time-based, protocol-defined services');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1fa64b8e-a030-42dc-a733-f551faedbac8', 'c3c10b95-b4c5-4f09-b1c2-75875d3665f4', 1, 'General documentation of ''counseling provided'' is sufficient regardless of which specific protocol or how much time was spent');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bd827a57-0ca1-485a-a97b-ea1ce952b38f', 'c3c10b95-b4c5-4f09-b1c2-75875d3665f4', 2, 'Time documentation is irrelevant to preventive counseling codes since these are always billed as flat per-visit fees');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f90a2219-c514-454b-8be9-ee440b3dca9d', 'c3c10b95-b4c5-4f09-b1c2-75875d3665f4', 3, 'Only the topic discussed (not time or protocol adherence) needs to be documented for any of these preventive counseling services');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('23192661-022a-4924-b89f-777a7dfb0ed8', '9c2bd3ce-6330-40e4-88fc-37449fef5a21', 0, 'Both may potentially be separately reportable when each is genuinely, separately identifiable and documented (with appropriate modifier use on the E/M code, e.g., modifier 25), consistent with the general same-day-multiple-distinct-service principle already established repeatedly throughout this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f1da4948-5d0d-491e-93e5-c58f44dec2a3', '9c2bd3ce-6330-40e4-88fc-37449fef5a21', 1, 'Only one of the two services may ever be billed on the same date, regardless of documentation for both');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a3437038-596a-4eb6-b51c-7d1e7bfcf33e', '9c2bd3ce-6330-40e4-88fc-37449fef5a21', 2, 'Preventive counseling is always bundled into any same-day problem-oriented E/M service with no separate reporting ever possible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('13cc0514-b8a7-4216-936c-121e87aa6cec', '9c2bd3ce-6330-40e4-88fc-37449fef5a21', 3, 'The two services must always occur on different calendar dates to both be billable');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d9291a08-8e73-44ff-b74a-8c7412dad557', '784ceb26-0e5b-46a6-8ab8-94f9956a37cb', 0, 'Genetic counseling (discussing testing implications, family history, informed consent) may have its own specific code(s) distinct from the genetic test itself, reflecting that counseling and testing represent genuinely different service types (cognitive/counseling service vs. laboratory analysis) even when closely related in the overall clinical pathway');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('72969425-0fc9-4f17-b0e9-da674d78c513', '784ceb26-0e5b-46a6-8ab8-94f9956a37cb', 1, 'Genetic counseling is always included in the genetic test code with no separate reporting ever possible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a8ecdb9b-d241-4504-b8ce-897ceb6192cd', '784ceb26-0e5b-46a6-8ab8-94f9956a37cb', 2, 'Genetic counseling is coded identically to the molecular pathology test code already discussed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ff578587-00eb-41b3-9438-e5b2efcf6364', '784ceb26-0e5b-46a6-8ab8-94f9956a37cb', 3, 'Genetic counseling has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('85851106-c4f7-4c3d-8762-a0f76d19f819', '0b7b7f6d-168d-406f-b5d0-0277e1aeecc6', 0, 'Identify the SPECIFIC defined counseling protocol/service model actually documented (general risk-factor counseling, smoking cessation, SBIRT, obesity intensive behavioral therapy, genetic counseling), its format (individual/group), and actual time spent — then match to the correct specific code, recognizing that ''preventive counseling'' encompasses multiple genuinely distinct, specifically-coded service types rather than being a single undifferentiated category');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4108984c-ba29-4d17-80b7-224c75c4884e', '0b7b7f6d-168d-406f-b5d0-0277e1aeecc6', 1, 'All preventive counseling services are billed using a single generic counseling code regardless of topic, format, or specific protocol followed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c1b6eeff-ebb6-43d2-8848-24a096d49220', '0b7b7f6d-168d-406f-b5d0-0277e1aeecc6', 2, 'Preventive counseling codes require an entirely separate analytical approach unrelated to the broader E/M-section principles already established throughout this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6ca51539-8d7b-41cb-a758-f3c4a387926e', '0b7b7f6d-168d-406f-b5d0-0277e1aeecc6', 3, 'Rely on the general topic discussed (e.g., ''weight'' or ''smoking'') alone to determine the correct code, without confirming which specific defined protocol/service model was actually followed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('59baced1-ecf9-48ab-839f-4b9c3a43c3b7', 'e4529779-1d2d-4467-992f-5da3fba321f5', 0, 'Both the AWV code and an appropriate problem-oriented E/M code (with modifier 25 appended to the E/M code) may be separately reportable, since the AWV itself is not a comprehensive physical exam covering acute problems — mirroring the same-day preventive-visit-plus-distinct-problem principle already established generally');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('045a20ad-ac08-4336-ba65-479727ee5d2e', 'e4529779-1d2d-4467-992f-5da3fba321f5', 1, 'The AWV always covers and bundles any acute problem addressed during the same visit with no separate E/M reporting ever possible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e0257736-26c8-4867-a11b-41c438941cdf', 'e4529779-1d2d-4467-992f-5da3fba321f5', 2, 'Only the problem-oriented E/M code may be billed; the AWV itself becomes unbillable once any other problem is addressed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('140514ac-d1b1-4aac-84f9-61fdfe2c2c64', 'e4529779-1d2d-4467-992f-5da3fba321f5', 3, 'AWV and problem-oriented E/M can never both occur during the same visit under any circumstance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0bda5b11-54b9-4434-b4da-64e55968685c', 'f6006172-27ef-4354-8997-e74e950e182f', 0, 'The HRA (a structured tool assessing the beneficiary''s health status, risk factors, and functional ability) is a required, defined component of the AWV, meaning its completion/documentation is relevant to supporting that the AWV''s specific defined scope was actually fulfilled');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b31ef369-3990-476d-9d55-e931082e5db6', 'f6006172-27ef-4354-8997-e74e950e182f', 1, 'The HRA is an entirely optional, unrelated add-on service with no bearing on AWV code selection or completeness');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('55002450-5d0c-40fb-82c4-b32694061f69', 'f6006172-27ef-4354-8997-e74e950e182f', 2, 'The HRA is a separately billable code, entirely distinct from and unrelated to the AWV service itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a5927636-6ebb-4d3b-a88c-d29282a423ba', 'f6006172-27ef-4354-8997-e74e950e182f', 3, 'The HRA applies only to the IPPE (Welcome to Medicare visit), never the recurring AWV');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ccaba2e8-8874-4820-a109-8a2009b299d1', '9a530268-e730-4784-a485-77f513758f01', 0, 'Both may be separately reportable — the IPPE code for the comprehensive initial preventive exam, and the vaccine product-plus-administration codes (per the general vaccine coding structure already established) for the immunization — since these represent genuinely distinct service components performed at the same visit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8bab4abf-e482-419d-b929-3e1b621b0599', '9a530268-e730-4784-a485-77f513758f01', 1, 'The vaccine is always bundled into the IPPE code with no separate reporting ever possible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('424953ee-c59a-4784-981e-8e5ebb374095', '9a530268-e730-4784-a485-77f513758f01', 2, 'Only the vaccine may be billed; the IPPE itself becomes unbillable if any vaccine is also given at the same visit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d5c3d239-405f-4247-a9b4-6cf85706f510', '9a530268-e730-4784-a485-77f513758f01', 3, 'IPPE and vaccine administration can never both occur during the same visit under any circumstance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2389fd24-d497-44f9-9b2f-2d627073d3bd', '4e716dcf-37d0-495c-8297-d8118ed251ff', 0, 'Depending on payer policy and whether a specific standalone screening code applies or the screening is considered part of the E/M service''s own MDM/history-gathering process, documentation should reflect what was actually performed — reinforcing the general principle that even a seemingly simple screening tool''s coding treatment depends on the specific applicable code structure/payer policy, not a single universal assumption');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1d131fbd-0371-45ab-821c-6a57dcc1c75c', '4e716dcf-37d0-495c-8297-d8118ed251ff', 1, 'Depression screening always has its own separately billable code regardless of payer policy or context');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('75b2238d-ceb9-49de-aef1-a46e1b913ff3', '4e716dcf-37d0-495c-8297-d8118ed251ff', 2, 'Depression screening is never separately relevant to coding under any circumstance, always fully absorbed into the E/M visit with zero distinct consideration');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3310b950-8118-4d9a-9234-b12fa0bb993b', '4e716dcf-37d0-495c-8297-d8118ed251ff', 3, 'Depression screening coding depends solely on the PHQ-9 numeric score, not on which specific code structure/payer policy actually applies');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2e3ba05f-9c9d-4b0f-949e-f55eb7eb9fe5', 'a5d39cde-c29a-4c7a-91a0-a3f4c4baab40', 0, 'Given the recurring compliance theme already established for modifier 25 generally, periodic review of whether the same-day problem-oriented E/M service is genuinely significant/separately identifiable (versus routine, minor issues that don''t independently warrant separate E/M billing alongside every AWV) is a reasonable, targeted compliance practice for this specific, common billing pattern');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('83f32e7d-ca80-4d3b-95e6-452fa84f48e4', 'a5d39cde-c29a-4c7a-91a0-a3f4c4baab40', 1, 'AWV-plus-modifier-25 billing patterns carry no distinct compliance considerations from any other same-day service combination');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c6daf3fb-b16b-476d-9105-3192eff91d17', 'a5d39cde-c29a-4c7a-91a0-a3f4c4baab40', 2, 'Every AWV should always be billed with an accompanying modifier-25 E/M service to maximize appropriate reimbursement, regardless of whether a genuinely significant separate problem was addressed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c2c439ff-27f3-4dc9-aa8e-b391cd4071de', 'a5d39cde-c29a-4c7a-91a0-a3f4c4baab40', 3, 'Modifier 25 compliance concerns apply only to preventive-visit-plus-E/M combinations, never any other same-day service pairing');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('21f6681a-debb-48b0-8b6c-24748369b0fb', 'd446d5cf-19fd-443d-aac3-f5ffd89a570a', 0, 'A pre-operative clearance visit performed by a DIFFERENT physician (e.g., the patient''s primary care physician or a cardiologist, at the surgeon''s request) is coded using standard E/M codes (or a consultation code, if applicable and payer-recognized) by that clearing physician — distinct from the operating surgeon''s own pre-operative visit, which is generally included in that surgeon''s global surgical package');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d3786da6-22ce-4102-a36f-77418ed5a3a9', 'd446d5cf-19fd-443d-aac3-f5ffd89a570a', 1, 'Pre-operative clearance visits by any physician are always included in the operating surgeon''s global surgical package, regardless of which physician performs the clearance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('86133939-72cf-4d61-8e18-1608bf753a80', 'd446d5cf-19fd-443d-aac3-f5ffd89a570a', 2, 'Pre-operative clearance has no distinct CPT code and must use an unlisted procedure code regardless of which physician performs it');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4b3d367f-688e-4d75-9db1-0ec30d12d9de', 'd446d5cf-19fd-443d-aac3-f5ffd89a570a', 3, 'Only the operating surgeon may ever bill for any pre-operative evaluation, regardless of which other physician actually performed the clearance visit');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0c267a07-2114-41c0-b4fd-09fbd4a6ddc4', '0405595b-f22d-4c94-9654-575215eda4ec', 0, 'Documentation should reflect the clearing physician''s own independent evaluation/medical decision making regarding surgical fitness (e.g., cardiac risk stratification), since this represents genuinely distinct clinical work from the surgeon''s own pre-operative assessment, supporting separate billability by the clearing physician');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('86b7d13f-fb80-4fc8-836b-a88966517640', '0405595b-f22d-4c94-9654-575215eda4ec', 1, 'No specific documentation is needed since any physician''s pre-operative note is automatically billable regardless of content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3a447d57-f505-4869-a7dc-8f8c744a2c1d', '0405595b-f22d-4c94-9654-575215eda4ec', 2, 'Pre-operative clearance documentation must be identical in content to the surgeon''s own pre-operative note to be considered valid');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('453ffd7f-36a1-48ca-8c1d-a3df8a89ed3c', '0405595b-f22d-4c94-9654-575215eda4ec', 3, 'Only the surgeon''s own documentation is ever relevant; the clearing physician''s documentation has no bearing on billability');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2dfcfe78-060a-428a-8fea-2d8836448790', '573a7d3b-d274-44c2-8090-d1f77aaad664', 0, 'Across all the E/M scenarios examined in this four-paper series — telehealth, critical care, split/shared billing, status changes, consultation/transfer-of-care, preventive services, and now specialized visit types like AWV and pre-op clearance — the recurring, transferable skill is identifying the SPECIFIC defined service structure, participant roles, and documentation requirements actually applicable to the exact clinical scenario, rather than applying office-visit E/M logic as a default template to every encounter type');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b915296a-6fd3-4f2d-abe3-4420843c2081', '573a7d3b-d274-44c2-8090-d1f77aaad664', 1, 'E/M coding is fundamentally simple and requires no scenario-specific analysis once the basic time/MDM leveling concept is understood');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f1a4dff2-bcb4-418a-9312-36fdc280c384', '573a7d3b-d274-44c2-8090-d1f77aaad664', 2, 'Preventive services, wellness visits, and pre-operative clearance are rare edge cases with minimal real-world coding relevance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4e252010-4f8c-42e9-8ca2-054f44b593b8', '573a7d3b-d274-44c2-8090-d1f77aaad664', 3, 'All the E/M scenarios covered across this four-paper series ultimately reduce to the same single coding rule with no meaningful scenario-specific distinctions');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fa492bf2-9941-40b9-a32f-365df8164686', '777f2304-6b11-4af1-a5a7-be79a2069101', 0, 'MNT has its own specific code family reflecting services provided by a registered dietitian/nutrition professional, structurally distinct from physician-provided E/M or preventive counseling codes, reflecting the different provider type and service scope');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d011585f-5928-4cf4-bb7e-fa952ca71cf4', '777f2304-6b11-4af1-a5a7-be79a2069101', 1, 'MNT is coded identically to physician preventive counseling codes regardless of which provider type delivers the service');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1bc812f9-afe4-49bf-b36d-a8401129763d', '777f2304-6b11-4af1-a5a7-be79a2069101', 2, 'MNT has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('990581f8-72fc-4712-84ff-1d8fbd34e8b8', '777f2304-6b11-4af1-a5a7-be79a2069101', 3, 'MNT coding depends solely on the specific diagnosis being addressed, not the provider type or service structure');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9eb1a869-c7e6-428b-934c-023e7c53c4ef', '4f9deb9e-5d02-4e2b-8f19-cbf270d24ca5', 0, 'Despite all being broadly ''counseling''-oriented services, each represents its own specifically-defined service model (topic, format, provider type, and often a specific evidence-based protocol), reinforcing yet again the recurring CPT theme that a shared general descriptor (''counseling'') frequently encompasses multiple genuinely distinct, separately-coded services rather than a single interchangeable category');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c239e5e7-b042-43f5-befd-23da78f2165d', '4f9deb9e-5d02-4e2b-8f19-cbf270d24ca5', 1, 'All counseling-type services share a single universal code regardless of topic, provider type, or protocol followed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('edc95ff5-ee5a-4547-8460-e3e9aeacd6f9', '4f9deb9e-5d02-4e2b-8f19-cbf270d24ca5', 2, 'Counseling services are inherently too subjective to have specific CPT codes and are always billed as unlisted procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('697aacd6-1ffb-4b13-a29d-4f0848d7067c', '4f9deb9e-5d02-4e2b-8f19-cbf270d24ca5', 3, 'The distinction between these various counseling code families is purely academic with no real-world billing/coverage relevance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a44829cd-cbf7-4b37-be0c-ed735418800e', 'c43f680f-d1da-4860-ac31-02a563b3c5c8', 0, 'Ophthalmologic anesthesia (e.g., for cataract surgery) has its own specific applicable anesthesia code reflecting this specific procedure/anatomic region, generally reported at the MAC/monitored-sedation service level typical for this commonly outpatient, brief procedure — consistent with the general procedure/region-specific base-code principle already established');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e648c23b-b94c-4ef4-82af-cded87b40a1a', 'c43f680f-d1da-4860-ac31-02a563b3c5c8', 1, 'Cataract surgery anesthesia is always coded identically to a major open abdominal surgery''s anesthesia code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3636f3f0-0494-43d3-822f-d24efe74e378', 'c43f680f-d1da-4860-ac31-02a563b3c5c8', 2, 'Ophthalmologic anesthesia has no distinct CPT code and must use an unlisted anesthesia procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4a80bf88-7052-407b-ab98-1c3c650af590', 'c43f680f-d1da-4860-ac31-02a563b3c5c8', 3, 'Cataract surgery is never performed under anesthesia billed via the Anesthesia section; only local block administered by the surgeon is ever used');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7ee6171c-69f9-418f-9787-0fe6a695f2ac', '3bcbf516-9ca2-472d-885f-65a323b8fcad', 0, 'This scenario may involve modifier 47 (anesthesia by surgeon, already discussed in Paper 4) appended to the surgical procedure code, reflecting that the operating surgeon personally administered the anesthesia/block rather than a separate anesthesia provider');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1c853392-7960-4d89-aadf-9df9b0e1975f', '3bcbf516-9ca2-472d-885f-65a323b8fcad', 1, 'This scenario can never be separately coded or reflected in any way');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('700427d7-3a9c-4e0c-99f1-f1de0849eaca', '3bcbf516-9ca2-472d-885f-65a323b8fcad', 2, 'Modifier 47 applies only to general anesthesia scenarios, never regional blocks like retrobulbar/peribulbar injections');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a88d985c-0881-4220-95d3-d55ebf2eef6a', '3bcbf516-9ca2-472d-885f-65a323b8fcad', 3, 'The surgeon must always bill using a separate anesthesia-section code identical to what an anesthesiologist would use for the same case');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('59635fea-5d23-4998-81a0-a9b47bd0c0d6', 'c55fc0fe-063e-4526-94ac-50a51b867c19', 0, 'The extreme-age qualifying circumstances add-on code (already established generally) may be appropriately reportable in addition to the base ophthalmologic anesthesia code, when the patient''s young age genuinely qualifies per that code''s specific age threshold and is documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0c55b127-3fc4-4b61-9886-d810125aa984', 'c55fc0fe-063e-4526-94ac-50a51b867c19', 1, 'Pediatric ophthalmologic anesthesia is always coded using an entirely separate, unrelated base code from adult ophthalmologic anesthesia for the identical procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('598d7e10-d1c8-40a5-b1ef-61a3900f2339', 'c55fc0fe-063e-4526-94ac-50a51b867c19', 2, 'Qualifying circumstances codes never apply to ophthalmologic procedures under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('46ee317b-bfb9-4df6-8b07-2e8a3b49d3ee', 'c55fc0fe-063e-4526-94ac-50a51b867c19', 3, 'Strabismus surgery in children is never performed under any form of anesthesia requiring CPT coding');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('87a6b4ad-0ea7-4242-87fc-5bc6da51fce0', '29fc30c0-68c4-46e4-bfeb-2a7caef9fe19', 0, 'The appropriate ophthalmologic anesthesia code is reported by the anesthesia provider, generally without modifier 47 (since modifier 47 specifically addresses SURGEON-administered anesthesia, not a separate anesthesia provider''s service) — reinforcing when modifier 47 does and does NOT apply');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2e8dfca3-2882-422f-94ca-edf27a7bc8f4', '29fc30c0-68c4-46e4-bfeb-2a7caef9fe19', 1, 'Modifier 47 must always be appended regardless of which type of provider administers the anesthesia');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('44dacce8-d15e-4468-ab0e-1c603c06c75f', '29fc30c0-68c4-46e4-bfeb-2a7caef9fe19', 2, 'A separate anesthesia provider can never bill for ophthalmologic anesthesia services');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9be2642c-db9c-47fd-a69f-70295793f18c', '29fc30c0-68c4-46e4-bfeb-2a7caef9fe19', 3, 'This scenario requires an entirely different code structure from the surgeon-administered-block scenario already discussed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('01ff4b90-31fc-43d1-b847-212306a8468a', 'febc566a-8248-4330-9887-9e9eaa9e286d', 0, 'The medical record should clearly identify WHO administered the anesthesia/block (the operating surgeon personally, or a separate anesthesia provider), since this specific documented fact determines whether modifier 47 applies to the surgical code or a standard anesthesia-section code applies to a separate anesthesia provider''s own claim');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0082f65d-f93b-4908-867a-181e36fbdfb9', 'febc566a-8248-4330-9887-9e9eaa9e286d', 1, 'No documentation of who administered the anesthesia is needed since this detail has no bearing on correct coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d78f38c0-7488-4442-9699-b4bebe405ada', 'febc566a-8248-4330-9887-9e9eaa9e286d', 2, 'This distinction is relevant only for billing purposes, never for the anesthesia record''s own clinical documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('71385ce0-0321-45f2-979a-0773ba2ccfdd', 'febc566a-8248-4330-9887-9e9eaa9e286d', 3, 'The distinction between surgeon-administered and separate-provider-administered anesthesia applies only to general anesthesia, never regional blocks');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e7fccd0c-94bd-4f2f-b6cc-5c474d2dd6b8', 'fc254b2b-d0d1-4314-a0eb-3ce5d9454899', 0, 'Apply the same core anesthesia-coding analytical framework already established throughout this content — procedure/region-specific base code, accurate physical status modifier, qualifying circumstances where genuinely documented, and correct identification of WHO administered the anesthesia (surgeon vs. separate provider, per modifier 47''s specific applicability) — recognizing ophthalmologic anesthesia as a concrete application of these same general principles rather than requiring an entirely new framework');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('813471ea-8cb4-4843-beac-f1ab6d762284', 'fc254b2b-d0d1-4314-a0eb-3ce5d9454899', 1, 'Ophthalmologic anesthesia requires an entirely separate, unrelated coding framework from general anesthesia coding principles');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9284302c-5186-4ce9-8070-0fb573dd78fc', 'fc254b2b-d0d1-4314-a0eb-3ce5d9454899', 2, 'Modifier 47 applies to every ophthalmologic anesthesia case by default, regardless of who actually administered the anesthesia');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ab007c97-1a1f-4482-9119-26567a46efc5', 'fc254b2b-d0d1-4314-a0eb-3ce5d9454899', 3, 'Ophthalmologic anesthesia coding depends solely on which eye (left/right) is operated on, with no other coding considerations relevant');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('08c41122-74fa-4ba7-8269-d2fe22b2b138', 'ac0890b7-9ecc-49dd-9b93-aff8dda6f37a', 0, 'Anesthesia for dental procedures requiring general anesthesia has its own applicable anesthesia code(s) reflecting the specific procedure/region, similar to how anesthesia extends to other non-traditionally-''surgical'' contexts (diagnostic imaging, ECT) already discussed — anesthesia coding isn''t limited to traditional surgical specialties');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fa0bfcae-a60b-4935-9962-bfdf0a1f0037', 'ac0890b7-9ecc-49dd-9b93-aff8dda6f37a', 1, 'Dental anesthesia can never be billed using CPT anesthesia codes under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9f4f9a4f-016a-4ce8-8f37-eb514db89622', 'ac0890b7-9ecc-49dd-9b93-aff8dda6f37a', 2, 'Dental anesthesia is coded identically to ophthalmologic anesthesia regardless of the actual procedure/region');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aef873bd-6910-40c6-b788-e20e91fdb04d', 'ac0890b7-9ecc-49dd-9b93-aff8dda6f37a', 3, 'Dental procedures requiring anesthesia must always use an unlisted anesthesia procedure code, with no specific applicable code ever existing');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('df7bed53-81c0-4113-ac21-a1e37db42317', 'f8ea863d-4d0c-43c3-8d06-62ea8e619fb3', 0, 'The applicable procedure/region-specific anesthesia code for that endoscopic procedure is reported by the anesthesia provider, distinct from the moderate sedation code family (already established as being used when the PROCEDURALIST personally provides sedation rather than a separate anesthesia provider delivering general anesthesia/MAC)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a0a3b899-f764-4616-b5ba-94cb7c8d8fd4', 'f8ea863d-4d0c-43c3-8d06-62ea8e619fb3', 1, 'Endoscopy anesthesia is always coded using the moderate sedation codes regardless of who provides it or what type of anesthesia is used');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('57ea1eb7-7b86-4f0d-9b0c-086161ca1c97', 'f8ea863d-4d0c-43c3-8d06-62ea8e619fb3', 2, 'Endoscopic procedures can never be performed under general anesthesia requiring Anesthesia-section coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ae3fde2b-1120-4525-a98d-23ca8e6a2ed7', 'f8ea863d-4d0c-43c3-8d06-62ea8e619fb3', 3, 'General anesthesia and moderate sedation for the same endoscopic procedure are coded identically with no distinction');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b5ded34a-18d7-4551-8e8b-1090aa67ffde', '21fe51ca-a27d-4c7d-a8ad-9883a6b4c716', 0, 'Documentation should clearly identify which sedation/anesthesia model was actually used (who administered it, and what type), since this directly determines whether the moderate sedation code family or the standard Anesthesia-section code family applies — the same WHO-and-WHAT documentation-specificity principle already established for the ophthalmology surgeon-versus-provider scenario');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5521c20f-7a4f-43e2-8b33-e10b03898e8f', '21fe51ca-a27d-4c7d-a8ad-9883a6b4c716', 1, 'No documentation of the specific sedation/anesthesia model is needed since both models are billed identically regardless of who administers what');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9723c73b-9731-4abe-8f75-c9f8f03ef754', '21fe51ca-a27d-4c7d-a8ad-9883a6b4c716', 2, 'This distinction is relevant only to anesthesia providers, never to the performing endoscopist''s own documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d5ea9894-599d-4fa7-8633-11eea4184650', '21fe51ca-a27d-4c7d-a8ad-9883a6b4c716', 3, 'Moderate sedation and general anesthesia/MAC are functionally identical concepts requiring no documentation distinction');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b239890a-e483-4fc3-9b41-b0d2856b72b9', '0e107bfa-97ca-4078-81b3-4b992ffadfda', 0, 'Despite spanning many different clinical contexts, Anesthesia-section coding consistently depends on the same core set of documented facts — the specific procedure/region, the patient''s actual physical status, any genuinely documented qualifying/complicating circumstances, WHO administered the anesthesia and in what role, and WHETHER the service falls under the Anesthesia-section base-code structure or a separate code family (moderate sedation, qualifying circumstances alone) — a consistent analytical framework applicable regardless of clinical specialty');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('280724fa-1343-4a34-a7e0-45b1a896e0b7', '0e107bfa-97ca-4078-81b3-4b992ffadfda', 1, 'Each clinical context requires an entirely separate, unrelated anesthesia coding framework with no common analytical thread');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('07399fb7-4fb5-4022-a52c-2087f758b597', '0e107bfa-97ca-4078-81b3-4b992ffadfda', 2, 'Anesthesia coding is fundamentally about selecting the highest-base-unit code available regardless of the actual documented clinical facts');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('365ffad0-5911-4b49-8789-380ba4f744ca', '0e107bfa-97ca-4078-81b3-4b992ffadfda', 3, 'The clinical context (surgical vs. obstetric vs. dental vs. endoscopic) is irrelevant to anesthesia coding, which depends solely on total time regardless of context');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8f72c06f-f1a4-4a6b-b0ff-01afafedebf1', 'ff0b9440-9ae3-41a1-a0c7-8d6e3178a82f', 0, 'Abdominoplasty (cosmetic) and panniculectomy (functionally indicated) have distinct codes reflecting the different surgical goal/indication, even though both involve removing abdominal skin/tissue — mirroring the earlier cosmetic-versus-functional coding distinction already established for nasal surgery');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d4a3f3bb-f4b6-47c9-b31c-289abfb6f108', 'ff0b9440-9ae3-41a1-a0c7-8d6e3178a82f', 1, 'Abdominoplasty and panniculectomy are always coded identically since both remove abdominal tissue');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6831e7c5-e345-414e-bd7f-5791bac44527', 'ff0b9440-9ae3-41a1-a0c7-8d6e3178a82f', 2, 'Panniculectomy has no distinct CPT code and must use the same code as abdominoplasty regardless of indication');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b0ea29dc-5050-4b7f-af3a-51864a4cd85a', 'ff0b9440-9ae3-41a1-a0c7-8d6e3178a82f', 3, 'Cosmetic versus functional indication has no bearing on which of these two codes applies');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('33f7253e-8c17-4a0e-92db-9fb11f3d2e28', '7066da49-8b59-46ee-855e-414104836994', 0, 'Free flap reconstruction (requiring microvascular anastomosis to establish blood supply at a distant recipient site) has its own specific, more complex code(s) distinct from a local/pedicled flap (which remains attached to its original blood supply), reflecting the significantly different surgical technique/complexity involved');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('acdc6f7b-d8ed-462b-913c-a2b2f2ffe165', '7066da49-8b59-46ee-855e-414104836994', 1, 'Free flap and local/pedicled flap reconstruction are coded identically regardless of technique');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('23f26b1d-114f-40fa-ad6f-ccb4e428d44f', '7066da49-8b59-46ee-855e-414104836994', 2, 'Free flap reconstruction has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a713b1e1-2732-4e1c-91a7-89b7150cb487', '7066da49-8b59-46ee-855e-414104836994', 3, 'The distinction between free and pedicled flaps has no bearing on CPT code selection, only flap size does');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ca8836c7-16c4-43c2-aae3-b3bec505a043', 'a9cc2756-ffb7-4053-858f-c8c80fd67ac1', 0, 'Depending on the specific flap code''s own descriptor, microvascular anastomosis may be included within the flap code itself or, in some code structures, relevant as a distinct component — requiring the same combined-versus-component code-descriptor verification already established as a recurring analytical step throughout this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('13e16b98-30c3-4728-9d33-95b2b9fd53fc', 'a9cc2756-ffb7-4053-858f-c8c80fd67ac1', 1, 'Microvascular anastomosis is always separately, fully billable in addition to every flap code regardless of that code''s own descriptor');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('23eb5ba3-227b-43d4-98f1-b558783896d1', 'a9cc2756-ffb7-4053-858f-c8c80fd67ac1', 2, 'Microvascular anastomosis has no relevance to free flap procedure coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3795c303-7cfc-47cd-999f-8375d717eb7d', 'a9cc2756-ffb7-4053-858f-c8c80fd67ac1', 3, 'Microvascular anastomosis is coded using the same code as a routine vascular access procedure');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
