INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('529a47da-7ae5-468c-9a8e-c7eb43e6ac72', '2279b305-7a67-41dc-ae81-3b7b9247cb30', 0, 'Standalone scar revision (performed as its own distinct procedure, separate from the original acute wound repair episode) may have its own specific code, distinct from the complex-repair wound-closure code used for scar revision performed AS PART OF acute wound closure at the time of injury — reflecting the different timing/context (delayed, standalone revision vs. immediate, injury-related complex closure)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('863434a3-21c2-44a7-9872-428007fc93da', '2279b305-7a67-41dc-ae81-3b7b9247cb30', 1, 'Scar revision is always coded identically regardless of whether it occurs as a standalone later procedure or as part of an acute complex wound repair');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ac2fdd80-03fc-4c6b-b6c2-374563b602f9', '2279b305-7a67-41dc-ae81-3b7b9247cb30', 2, 'Scar revision has no distinct CPT code under any circumstance and must always use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fe2d3073-dc78-4350-bc0c-499a245b9896', '2279b305-7a67-41dc-ae81-3b7b9247cb30', 3, 'The complex repair code and standalone scar revision code are functionally identical with no timing/context distinction');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('61b2ac49-75f9-417c-9dd8-61a6660246cd', '4ffd79a2-f1e2-4bd8-b4f2-4485e56c79f7', 0, 'Liposuction codes are generally structured by anatomic area treated, with correct coding depending on documentation of the SPECIFIC area(s) actually treated (regardless of whether the overall goal is characterized as body contouring or cosmetic), consistent with the general anatomic-specificity coding theme already established');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d7b2f26d-7f04-4818-b8be-3cc351a4a13d', '4ffd79a2-f1e2-4bd8-b4f2-4485e56c79f7', 1, 'Liposuction for body contouring and for purely cosmetic purposes are coded using entirely different, unrelated code sets');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5f14ecf2-1748-43d3-a2c3-fcf46b48ecf2', '4ffd79a2-f1e2-4bd8-b4f2-4485e56c79f7', 2, 'Liposuction has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cda84b51-a73c-4a7f-9664-c35e3adfa7ca', '4ffd79a2-f1e2-4bd8-b4f2-4485e56c79f7', 3, 'Liposuction coding depends solely on the total volume of fat removed, not the anatomic area(s) treated');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
