INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('78c70ff7-aaa5-4472-9a6c-0dabda7754d3', 'a557b6a9-7202-4f09-8144-6ca70ba1b060', 0, 'Endovenous ablation and traditional vein stripping/ligation have distinct codes reflecting the different technique/technology used, consistent with the approach/technique-specificity theme established repeatedly throughout this content across many procedure types');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('74fdd12c-ad50-4a3b-a7f6-c10f30daaf1c', 'a557b6a9-7202-4f09-8144-6ca70ba1b060', 1, 'Endovenous ablation and vein stripping are coded identically regardless of technique');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1c91e4bd-bb6b-423f-b945-74bc5a0aaa64', 'a557b6a9-7202-4f09-8144-6ca70ba1b060', 2, 'Endovenous ablation has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cb312eb1-bf28-4f24-aa0b-0c020de7e630', 'a557b6a9-7202-4f09-8144-6ca70ba1b060', 3, 'Varicose vein treatment coding depends solely on which leg is treated, not the specific technique used');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
