INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d59aa303-fc8d-4d05-9188-f513d020f289', 'ded5c4c4-9326-4813-8aaa-0e7ef2389e97', 0, 'Depending on the specific code structure, each distinct venous segment treated may be separately reportable (potentially via an add-on code for additional veins treated in the same extremity), similar to the base-code-plus-additional-site add-on structure already established for other multi-site procedures (spinal fusion levels, lesion excisions)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bd088cfd-0912-43e8-ae11-dedfbd71ff84', 'ded5c4c4-9326-4813-8aaa-0e7ef2389e97', 1, 'All venous segments treated in the same leg during the same session are always combined into a single code regardless of how many distinct segments were treated');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0af43fbc-8364-40b9-9329-82d596b4d2fb', 'ded5c4c4-9326-4813-8aaa-0e7ef2389e97', 2, 'Only one venous segment per leg per session may ever be coded, regardless of how many were actually treated');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c1fb8f46-5160-4c5a-80c2-501c50e59f1e', 'ded5c4c4-9326-4813-8aaa-0e7ef2389e97', 3, 'Multiple venous segment treatment in the same leg always requires two entirely separate operative sessions to each be coded');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
