INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('79b14522-76d1-4468-9919-1d8e48f4138c', '607fd1cb-8941-4e07-8bd4-a610a693ae63', 0, 'Sclerotherapy has its own specific code, distinct from endovenous ablation, reflecting the different technique (chemical injection vs. energy-based catheter ablation) typically used for smaller/more superficial veins versus larger truncal veins');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('faffcdce-4363-43f1-9c56-fe61a9684c77', '607fd1cb-8941-4e07-8bd4-a610a693ae63', 1, 'Sclerotherapy and endovenous ablation are coded identically regardless of technique or vein size/type treated');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0f6fb286-e7fd-40b8-a941-463dd2945148', '607fd1cb-8941-4e07-8bd4-a610a693ae63', 2, 'Sclerotherapy has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2962511f-0540-43d5-958d-379885336861', '607fd1cb-8941-4e07-8bd4-a610a693ae63', 3, 'Sclerotherapy coding depends solely on the total number of veins treated, not the technique used');
