INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ab391e69-300d-44c9-9786-7624d017ce35', '7ab13e37-e183-4841-8341-7211a43c80f9', 0, 'CPT amputation codes (like the ICD-10-PCS Detachment root operation already discussed) are structured by specific anatomic level (below-knee, above-knee, hip disarticulation, etc.), meaning the SPECIFIC documented level of amputation directly determines correct code selection, not a single universal ''leg amputation'' code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b10e071c-f117-4dda-a3f2-8cf324fad112', '7ab13e37-e183-4841-8341-7211a43c80f9', 1, 'All lower extremity amputations, regardless of level, are coded identically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4037df30-78ad-4b21-8a9f-9f90c0661d20', '7ab13e37-e183-4841-8341-7211a43c80f9', 2, 'Amputation level is relevant only to ICD-10-PCS coding, never CPT coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bac65b79-8b17-4f8f-84b2-0c75e7d420ca', '7ab13e37-e183-4841-8341-7211a43c80f9', 3, 'Below-knee amputation has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
