INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bccd7731-c86c-4d31-b4cd-bef48bb96a29', 'ad908017-9516-4a67-b1a5-f782f83a23b2', 0, 'Stump revision has its own specific code, distinct from the original amputation code, reflecting that revision represents a separate, later procedural event — consistent with the recurring original-procedure-versus-later-revision coding distinction already established extensively throughout this content for numerous other procedure/device types');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2304bc8d-7e04-43a8-aa33-318eb53af5e7', 'ad908017-9516-4a67-b1a5-f782f83a23b2', 1, 'Stump revision is always included in the original amputation code''s global period indefinitely, regardless of timing');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4d2a2a98-28e8-40cc-aeb5-ddc131e61c6a', 'ad908017-9516-4a67-b1a5-f782f83a23b2', 2, 'Stump revision is coded identically to the original amputation procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('679c5923-1bdc-4a42-bb6f-7f6a5b094a26', 'ad908017-9516-4a67-b1a5-f782f83a23b2', 3, 'Stump revision has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fa116a48-059f-4b43-b229-9dfca10c9c66', 'bf70c6bd-fa05-4a63-81e1-52b13105a98a', 0, 'If a specific code exists reflecting the immediate-post-operative-prosthetic-fitting technique/protocol, it should be used when that specific technique was actually documented as performed, rather than defaulting to the standard amputation code when a more specific, protocol-matching code actually exists and applies');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7937e898-5236-47d2-b64a-b01896543292', 'bf70c6bd-fa05-4a63-81e1-52b13105a98a', 1, 'Immediate and delayed prosthetic fitting scenarios are always coded identically regardless of the specific protocol/timing actually used');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3f2605bd-6baa-4b26-a7ef-8ee5b9277577', 'bf70c6bd-fa05-4a63-81e1-52b13105a98a', 2, 'Immediate post-operative prosthetic fitting is never a distinct coding consideration from a standard amputation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7d961966-65fa-46f1-bafe-497956ea77e3', 'bf70c6bd-fa05-4a63-81e1-52b13105a98a', 3, 'This distinction is relevant only to prosthetist billing, never to the surgeon''s own CPT procedure code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
