INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dd58d806-8e26-48a7-a339-c6b4a8d11c0b', '0f8011c6-fd13-4798-acd9-3c3d4b18c146', 0, 'Peripheral arterial bypass (e.g., popliteal-to-tibial) has its own specific code family, distinct from CABG, reflecting the different anatomic vascular territory (peripheral vs. coronary) even though both share the same underlying Bypass root-operation CONCEPT (rerouting blood flow around a blockage)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2c042c00-7ec3-4b24-a5c7-bc24a3e6401c', '0f8011c6-fd13-4798-acd9-3c3d4b18c146', 1, 'Peripheral arterial bypass and CABG are coded identically since both are bypass procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f8f6d1bd-1d8a-4266-abdd-e934f0a404c9', '0f8011c6-fd13-4798-acd9-3c3d4b18c146', 2, 'Peripheral arterial bypass has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b7b097af-dbce-4422-98a5-0a96961c50d5', '0f8011c6-fd13-4798-acd9-3c3d4b18c146', 3, 'Peripheral bypass coding depends solely on graft material used, not the specific vascular territory/anatomic location');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e6abf38a-4e93-4e4a-a66a-00fc9364f18f', 'aefed7da-5e80-47ec-b474-e7d4ec94fb7d', 0, 'Similar to the CABG graft-material qualifier concept already discussed, peripheral bypass codes may also account for the specific conduit type used (vein vs. synthetic/prosthetic graft), meaning this documented detail is relevant to correct, complete code selection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a5398154-d8db-4f89-a5b4-14e138610bfd', 'aefed7da-5e80-47ec-b474-e7d4ec94fb7d', 1, 'Graft material/conduit type is never a coding consideration for peripheral arterial bypass, unlike CABG');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1f71388b-e406-43f5-acfd-d79aa6f4e22f', 'aefed7da-5e80-47ec-b474-e7d4ec94fb7d', 2, 'All peripheral bypass grafts, regardless of conduit material, are coded identically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2ab49d3d-4650-40f1-9569-5239bd6c220d', 'aefed7da-5e80-47ec-b474-e7d4ec94fb7d', 3, 'Conduit type is relevant only to CABG coding, with zero applicability to peripheral vascular bypass procedures');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f5eec104-5db0-4b94-91e9-f33fdcc13f40', '85649a7e-ff5e-40c7-a93a-6879b1194ee0', 0, 'Carotid endarterectomy has its own specific code reflecting this distinct vascular surgery procedure (plaque removal from a specific artery), consistent with the general anatomic/procedure-specificity theme, and distinct from carotid artery stenting (an endovascular alternative technique for the same general clinical goal)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('12d5b804-0357-4a22-a1fc-053b9826d473', '85649a7e-ff5e-40c7-a93a-6879b1194ee0', 1, 'Carotid endarterectomy is coded identically to carotid artery stenting since both address carotid artery disease');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ee53c773-eabe-4263-aa51-697aff522c30', '85649a7e-ff5e-40c7-a93a-6879b1194ee0', 2, 'Carotid endarterectomy has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c3b9111e-34c8-4dfb-8d7e-84baf744f2f9', '85649a7e-ff5e-40c7-a93a-6879b1194ee0', 3, 'Carotid endarterectomy coding depends solely on the patient''s stroke risk score, not the actual procedure performed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
