INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4539dafb-a42e-4a18-8f31-6d5bbb0915de', '683ef713-9494-46d3-ab89-fcf7e89562bf', 0, 'EVAR and open aortic aneurysm repair have distinct codes reflecting the fundamentally different surgical approach (catheter-based endovascular graft placement vs. open surgical exposure and graft placement), consistent with the approach-specificity theme established throughout this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c7a988ef-4e5a-42ee-b102-2d3826196db7', '683ef713-9494-46d3-ab89-fcf7e89562bf', 1, 'EVAR and open repair are coded identically regardless of approach since both address the same aneurysm');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d915bd6d-1ef3-4a83-8aaf-8ae8afc8000b', '683ef713-9494-46d3-ab89-fcf7e89562bf', 2, 'EVAR has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4e2d97d8-df37-4c4a-add7-7729d8eaf107', '683ef713-9494-46d3-ab89-fcf7e89562bf', 3, 'Aortic aneurysm repair coding depends solely on aneurysm size, not the surgical approach used');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('45fba898-8ce3-4588-b026-5064465b4687', 'f2995fa2-6ca5-4124-b368-0bb1e565ae06', 0, 'Apply the same core analytical discipline demonstrated consistently across every surgical specialty examined in this series — specific indication (cosmetic vs. functional), approach/technique (free vs. pedicled flap, endovascular vs. open, ablation vs. stripping), anatomic specificity (level, territory, laterality), device/material/conduit used, and combined-versus-component code structure — recognizing this as the single, transferable analytical framework underlying accurate CPT Surgery-section coding regardless of specialty');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('43e926d0-b463-499f-9d10-dc3142591f80', 'f2995fa2-6ca5-4124-b368-0bb1e565ae06', 1, 'Plastic/reconstructive and vascular surgery require entirely separate, specialty-specific analytical frameworks unrelated to the principles established for other surgical specialties in this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d15689bb-97e2-4f2f-9f53-6f85111afdd8', 'f2995fa2-6ca5-4124-b368-0bb1e565ae06', 2, 'Assume all procedures within plastic/reconstructive or vascular surgery are coded using a small number of universal codes regardless of documented specifics');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('08f79817-f477-4c68-9597-0bac96775706', 'f2995fa2-6ca5-4124-b368-0bb1e565ae06', 3, 'Rely on the surgeon''s own procedure-note terminology/shorthand exclusively, without matching actual documented facts against precise code descriptors');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8894c3e9-f45e-475c-b2cd-cd923a329235', '93d1c225-f69c-4009-9494-2fd557bf7757', 0, 'Cosmetic facelift and reconstructive facial procedures have distinct codes reflecting the different indication/surgical goal, mirroring the cosmetic-versus-functional/reconstructive coding distinction already established for other body regions (nose, abdomen)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('af93203c-6ec2-4398-ae3f-669b4bf6a2c7', '93d1c225-f69c-4009-9494-2fd557bf7757', 1, 'Cosmetic and reconstructive facial procedures are always coded identically regardless of indication');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('54af45b0-31f1-4f71-8cc9-29483a0bb5f5', '93d1c225-f69c-4009-9494-2fd557bf7757', 2, 'Cosmetic facelift has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('77e20860-75b4-4adf-9ea6-af31798e75d6', '93d1c225-f69c-4009-9494-2fd557bf7757', 3, 'The distinction between cosmetic and reconstructive indication is irrelevant to facial procedure code selection');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fe312a2f-68f5-4daf-8f8f-ff319b9dbdcb', '22524db1-9d4e-4216-a9d3-7208e28b5325', 0, 'Functionally-indicated and cosmetic blepharoplasty may have different coding/coverage treatment, mirroring the general cosmetic-versus-functional distinction already established, with functional indication typically requiring specific supporting documentation (e.g., visual field testing showing obstruction) to support medical necessity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4e1f45e7-b2bb-4b2c-be13-4c4b9c454a56', '22524db1-9d4e-4216-a9d3-7208e28b5325', 1, 'Blepharoplasty is always considered purely cosmetic with no functional-indication coding/coverage pathway ever available');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e24ee6e2-e478-42a4-8d9d-36c916a79b73', '22524db1-9d4e-4216-a9d3-7208e28b5325', 2, 'Functional and cosmetic blepharoplasty are always coded and covered identically regardless of documented indication');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a5752139-c719-46bc-9d99-123834898a24', '22524db1-9d4e-4216-a9d3-7208e28b5325', 3, 'Blepharoplasty coding depends solely on which eyelid (upper/lower) is treated, not the functional-versus-cosmetic indication');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f6d8dac5-e5fd-4a64-b421-d8a924364cd4', '16e0229b-5853-4d78-8165-3cc8467a94a0', 0, 'Documentation should include objective supporting evidence (e.g., visual field testing demonstrating the excess skin''s obstruction of vision, photographs, and the physician''s own clinical assessment linking the excess skin to the documented functional impairment), consistent with the general documentation-supports-medical-necessity principle already established throughout this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a2afe824-f61c-41c8-8e70-b436b02e7a8d', '16e0229b-5853-4d78-8165-3cc8467a94a0', 1, 'No specific objective documentation is needed; the patient''s own subjective complaint of ''looking tired'' is sufficient to establish functional indication');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0b8fd504-ac15-4333-8cd9-ace3f0680816', '16e0229b-5853-4d78-8165-3cc8467a94a0', 2, 'Functional indication for blepharoplasty can never be documented or established under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('374187d5-ba8f-41b5-bf27-a00de49efa51', '16e0229b-5853-4d78-8165-3cc8467a94a0', 3, 'Only the surgeon''s own unsupported assertion of functional indication, without any objective testing, is required');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4ea65b8e-00a8-4442-8145-538f7cf374bc', 'dbe768ff-f97e-4af6-a809-3bfbe5f3a6e0', 0, 'Otoplasty has its own specific code, and while frequently performed for cosmetic/appearance reasons, coding/coverage may depend on documented indication and payer policy, similar to the cosmetic-versus-functional analysis already established for other plastic surgery procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ea693671-776b-4a73-aa6d-ddd2e3b13391', 'dbe768ff-f97e-4af6-a809-3bfbe5f3a6e0', 1, 'Otoplasty is always classified as purely functional/medically necessary regardless of the actual indication documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7d3e8ebe-09d2-440d-a866-1085ff11ac1d', 'dbe768ff-f97e-4af6-a809-3bfbe5f3a6e0', 2, 'Otoplasty has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('838600ba-d5e8-4c88-93a2-d7b477e52737', 'dbe768ff-f97e-4af6-a809-3bfbe5f3a6e0', 3, 'Otoplasty coding depends solely on the patient''s age, with no relevance for cosmetic-versus-functional indication analysis');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('85a36317-fb5c-41fd-907b-beb97e63b1fa', '2a12876f-7485-4770-848f-4a35fdab4e84', 0, 'Gender-affirming procedures are coded using the same underlying anatomic/technique-specific CPT codes already used for analogous procedures performed for other indications (e.g., mastectomy codes, genital reconstruction codes), with correct code selection depending on the SPECIFIC procedure/technique actually performed, consistent with the general procedure-specificity coding principle already established throughout this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4c6998eb-e3d2-405c-8e23-0b2fd3ef1734', '2a12876f-7485-4770-848f-4a35fdab4e84', 1, 'Gender-affirming procedures require an entirely separate, unique code set unrelated to any other procedure codes in CPT');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ddb69daa-4f8a-4168-b313-26b0aa0632f6', '2a12876f-7485-4770-848f-4a35fdab4e84', 2, 'Gender-affirming procedures have no CPT codes at all and must always use unlisted procedure codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6e5c1cb4-fe0c-4e10-aa6f-c3a3792aea68', '2a12876f-7485-4770-848f-4a35fdab4e84', 3, 'Code selection for gender-affirming surgery depends solely on the patient''s legal documentation status, not the actual surgical procedure/technique performed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3d97d313-ebad-4982-82c9-05d207db7895', '1c09c863-d9d0-4ea4-941c-c9600e7534b3', 0, 'Documentation should specify the actual procedure/technique performed (as with any procedure), and separately, medical necessity/coverage documentation (per applicable payer policy for gender-affirming care) should be maintained as its own distinct compliance consideration, since code selection (procedure-based) and coverage determination (policy-based) are related but distinct questions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('26381f4f-15ac-44a9-8848-06b9508b8b81', '1c09c863-d9d0-4ea4-941c-c9600e7534b3', 1, 'No distinct documentation practice applies to gender-affirming procedures beyond standard procedure documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fb1ccd88-d132-4f53-9940-5ad86935a95e', '1c09c863-d9d0-4ea4-941c-c9600e7534b3', 2, 'Gender-affirming procedure documentation requirements are entirely unrelated to any general documentation principles already established in this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('71613734-3d3a-4042-bfe6-8854ccb30df5', '1c09c863-d9d0-4ea4-941c-c9600e7534b3', 3, 'Medical necessity documentation is never relevant to gender-affirming procedures under any payer''s policy');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('724fb5a2-3ebb-4df8-86cf-c1cf3401d404', '15f967e6-dcfc-4077-a7b5-cd86472098d5', 0, 'The same tissue expansion coding principles (temporary expander placement, later exchange/reconstruction) already established for breast reconstruction apply conceptually to other body regions, though the SPECIFIC codes used would reflect the actual anatomic region being reconstructed, not the breast-specific codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2e1711a8-11d0-4d32-b575-f48476f2b08a', '15f967e6-dcfc-4077-a7b5-cd86472098d5', 1, 'Tissue expansion codes apply exclusively to breast reconstruction and can never be used for any other body region');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cf3b4ad2-d7a6-4406-890a-b25bac5e5da0', '15f967e6-dcfc-4077-a7b5-cd86472098d5', 2, 'Burn scar reconstruction via tissue expansion is coded identically to breast tissue expansion regardless of body region');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e42b0e54-468a-4811-b247-335434eae0b9', '15f967e6-dcfc-4077-a7b5-cd86472098d5', 3, 'Tissue expansion has no distinct CPT code outside of breast reconstruction contexts');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ec9e74dd-5c5c-4a0f-ba05-f39d03b57050', '8a2581bb-6f1b-4e67-b42d-e72d812305f4', 0, 'Application of a skin substitute/cellular tissue product has its own specific code(s), generally distinct from both standard excisional debridement and traditional autograft/allograft skin grafting, reflecting this as its own distinct category of advanced wound care technology/technique');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d8153e9a-91b1-4430-8d69-7296f441815e', '8a2581bb-6f1b-4e67-b42d-e72d812305f4', 1, 'Skin substitute application is coded identically to traditional skin grafting regardless of the different product/technique involved');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d2338732-9c7b-444e-9a9e-ac62fa055513', '8a2581bb-6f1b-4e67-b42d-e72d812305f4', 2, 'Skin substitute application has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5ded905e-ca81-4395-90e4-167c7ca63c7b', '8a2581bb-6f1b-4e67-b42d-e72d812305f4', 3, 'Skin substitute coding depends solely on wound size, with no distinction from standard debridement coding');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a37c4942-04d1-4834-9588-76fc29410d16', '68983391-787e-4191-b59a-9df20f0e7014', 0, 'Both may potentially be separately reportable, since debridement (preparing the wound bed) and skin substitute application (a distinct subsequent step) represent genuinely different components of the overall wound care encounter — consistent with the general ''genuinely distinct additional procedural components, separately reportable'' principle already established repeatedly throughout this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a8bb1896-428d-4cbc-a067-3e0a7633e9f3', '68983391-787e-4191-b59a-9df20f0e7014', 1, 'Debridement is always bundled into the skin substitute application code with no separate reporting ever possible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c07146b4-1785-40f4-8f6a-5367f5d67f47', '68983391-787e-4191-b59a-9df20f0e7014', 2, 'Only the debridement is ever coded, with the skin substitute application considered automatically included');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1a497a92-88ce-4f95-b5b6-f940ed64c194', '68983391-787e-4191-b59a-9df20f0e7014', 3, 'Debridement and skin substitute application can never both be performed in the same encounter');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('25571ce3-a62b-4119-8980-d3df2bc1014c', '0dcedcde-436a-44ec-9daa-ac6e08fdcdb4', 0, 'Given the significant cost of these products (often billed via HCPCS Level II codes for the product itself, separate from the CPT application procedure code, mirroring the product-plus-procedure separation pattern already established generally), ensuring documentation supports genuine medical necessity for the specific product/application (not routine, undifferentiated use regardless of wound characteristics) is a reasonable, targeted compliance consideration given known payer/OIG scrutiny of this category');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0788cfaa-32b5-4e51-bf27-9573da2dc4fd', '0dcedcde-436a-44ec-9daa-ac6e08fdcdb4', 1, 'Skin substitute products carry no distinct compliance considerations from any other wound care supply');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d9b99b1b-c641-4f79-8e17-394f5afcf8c3', '0dcedcde-436a-44ec-9daa-ac6e08fdcdb4', 2, 'These products should be applied to every chronic wound regardless of characteristics, to ensure the most advanced care is always provided without cost consideration');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d3c52bb0-f550-45f6-ace8-d5c3d342a54b', '0dcedcde-436a-44ec-9daa-ac6e08fdcdb4', 3, 'Compliance review of skin substitute product use and billing is unnecessary since these are FDA-approved products');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b496b8ee-8d00-419e-9c1f-f246d62f2255', '0f2e8ed1-92b3-4195-a748-4d701497459c', 0, 'Depending on the specific product/technique and code structure, incisional (closed-incision) NPWT may have distinct coding considerations from open-wound NPWT already discussed, reflecting the different clinical application (preventive, over a closed incision, versus therapeutic, over an open wound) — requiring the same code-specific verification discipline established throughout this content rather than assuming identical treatment');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3190d841-c852-479c-b358-b81f5eae6af3', '0f2e8ed1-92b3-4195-a748-4d701497459c', 1, 'Incisional and open-wound NPWT are always coded identically regardless of the clinical application');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fa7c571a-e3b8-46d4-b327-154412abf311', '0f2e8ed1-92b3-4195-a748-4d701497459c', 2, 'Incisional NPWT has no distinct coding consideration and is never separately relevant from standard wound VAC coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ca3e1e8b-b2f4-4f29-8882-ab3f248bc00d', '0f2e8ed1-92b3-4195-a748-4d701497459c', 3, 'NPWT coding depends solely on the device brand used, not the clinical application/wound type');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d33afddb-b75a-4c7c-b95b-8fa4847fe36b', 'bf2b4f73-00e2-4436-ad75-1e8b1586ef43', 0, 'The donor site (where the graft is harvested from) is generally considered part of the overall grafting procedure and its associated wound care, though very large or complicated donor site management could, in some documented circumstances, warrant additional consideration — requiring attention to the specific code descriptor''s scope and any applicable guidelines');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('37242127-d1a4-4343-9c71-53d2cb118e2c', 'bf2b4f73-00e2-4436-ad75-1e8b1586ef43', 1, 'The donor site is always separately, fully coded as an entirely distinct procedure from the graft placement itself, regardless of size or complexity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('87aa2ede-0f73-4f0e-aa7c-08805b8ee50a', 'bf2b4f73-00e2-4436-ad75-1e8b1586ef43', 2, 'Donor site management has no relevance to skin graft coding whatsoever, under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dc7abe45-3857-4e2f-bfc9-a2c0c14a6aa6', 'bf2b4f73-00e2-4436-ad75-1e8b1586ef43', 3, 'Only the recipient site, never the donor site, is ever mentioned or relevant to skin graft documentation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a2019f4c-f5fc-45e4-b83a-19ffa7e76eea', '8b511ac2-2fad-4e3f-9a40-18c8528622a9', 0, 'This is a genuinely recurring, cross-anatomic-region CPT/coverage principle — the same underlying analytical question (is this procedure functionally/medically indicated, or purely cosmetic/elective) applies across many different body regions and procedure types, with correct coding/coverage determination depending on documented indication rather than the specific anatomic region or procedure name alone');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('13481727-de55-4da7-ac8b-6e2ebe73a8ca', '8b511ac2-2fad-4e3f-9a40-18c8528622a9', 1, 'The cosmetic-versus-functional distinction is relevant only to nasal surgery and has no broader applicability to other body regions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aacc67f0-5ad8-40fe-9436-281bc84f778d', '8b511ac2-2fad-4e3f-9a40-18c8528622a9', 2, 'All plastic surgery procedures are automatically classified as purely cosmetic with no functional-indication pathway ever available for any procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9a9696fd-d2ef-444c-8a39-4280ac3b502f', '8b511ac2-2fad-4e3f-9a40-18c8528622a9', 3, 'Cosmetic-versus-functional determination is based solely on which medical specialty performs the procedure, not the documented clinical indication');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('855cd205-0c2e-4e62-90f7-72bf7c6266ec', '7157a7d9-c661-4de8-b60c-b2f6a6c73fa5', 0, 'Treatment of a genuine medical complication arising from a prior cosmetic procedure (e.g., infection requiring drainage, or implant removal for rupture) is generally coded based on the actual complication/procedure being addressed now, which may be medically necessary and separately codeable/coverable even though the ORIGINAL procedure was cosmetic and not covered');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c33f6b5d-2556-425d-b68e-8ba9825dafc5', '7157a7d9-c661-4de8-b60c-b2f6a6c73fa5', 1, 'Any complication arising from an originally cosmetic procedure can never be coded or covered as medically necessary, regardless of the actual current clinical circumstances');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('842ea2ea-6604-406d-a055-d9034bfeaffa', '7157a7d9-c661-4de8-b60c-b2f6a6c73fa5', 2, 'Complication treatment is always coded identically to the original cosmetic procedure, with no distinction for the different, current medical indication');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f979679c-2b27-46be-822c-d995664177e3', '7157a7d9-c661-4de8-b60c-b2f6a6c73fa5', 3, 'Cosmetic-procedure complications are never separately identifiable from the routine expected recovery course of any cosmetic procedure');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1be2f469-c38e-4eb5-8b83-6b8cc2d30ee0', 'f40b4c6c-a8f7-4bd2-b427-d886c0414428', 0, 'Axial and peripheral DEXA studies have distinct codes reflecting the different anatomic sites/clinical purposes studied, consistent with the general anatomic-site-specificity theme already established for radiology coding broadly');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d4b6eae9-2917-46aa-8b14-edca91b358f5', 'f40b4c6c-a8f7-4bd2-b427-d886c0414428', 1, 'Axial and peripheral DEXA are coded identically regardless of which sites are studied');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b2c6aa52-fc74-4e19-b2fb-7a1266ca23ac', 'f40b4c6c-a8f7-4bd2-b427-d886c0414428', 2, 'Peripheral DEXA has no distinct CPT code and must use an unlisted radiology procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('483106c3-61e2-426c-8471-fdd1109b2494', 'f40b4c6c-a8f7-4bd2-b427-d886c0414428', 3, 'DEXA code selection depends solely on the DEXA machine manufacturer, not the anatomic sites studied');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e0989431-120d-425f-9ad0-7a5393b83f11', 'fe5ae80f-7f10-4ad2-96fd-a2d3c3eb48fc', 0, 'VFA (a specific imaging assessment for vertebral compression fractures, often performed using DEXA equipment) may have its own specific code, distinct from the standard bone density measurement code, reflecting this as a distinct diagnostic assessment even when performed using the same equipment/visit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6bcacc3b-9a45-4854-9d2a-d169fe6fb127', 'fe5ae80f-7f10-4ad2-96fd-a2d3c3eb48fc', 1, 'VFA is always included in the standard DEXA bone density code with no separate reporting ever possible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4c28eb9f-653c-4310-9ccb-7fd9886e4782', 'fe5ae80f-7f10-4ad2-96fd-a2d3c3eb48fc', 2, 'VFA has no distinct CPT code and must use an unlisted radiology procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d16b22f6-7d2d-40de-931b-15031cadc730', 'fe5ae80f-7f10-4ad2-96fd-a2d3c3eb48fc', 3, 'VFA is coded using the same code as a routine spine X-ray');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8fee8215-249e-4096-882c-98d2822dfa33', '49418a72-9342-47f1-ace7-634f8728cb66', 0, 'Fluoroscopic guidance may have its own separately reportable code, when the specific joint injection code doesn''t already bundle guidance into its own descriptor — consistent with the general imaging-guidance bundling analysis already established repeatedly throughout this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3feff262-e300-460b-a871-3d173baf1cfc', '49418a72-9342-47f1-ace7-634f8728cb66', 1, 'Fluoroscopic guidance is never separately reportable for joint injections under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6b7d8110-5e22-4baf-8f3d-b425b510d1f6', '49418a72-9342-47f1-ace7-634f8728cb66', 2, 'Fluoroscopic guidance is always bundled into every joint injection code regardless of that code''s own descriptor');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('60ffa112-06ff-4587-975f-e675209c7a62', '49418a72-9342-47f1-ace7-634f8728cb66', 3, 'Fluoroscopic guidance for joint injections requires an entirely separate anesthesia code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4de18975-9ad5-4e20-8f86-16dc21332386', 'f7f645de-6549-4cea-a3cf-15a345f98d91', 0, 'Image-guided lumbar puncture may have an applicable guidance code (or a specific combined code) distinct from a landmark-based lumbar puncture without imaging guidance, reflecting the different technique/technology actually used');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8b19411f-7cda-4b96-b76f-64821ad7a35d', 'f7f645de-6549-4cea-a3cf-15a345f98d91', 1, 'Guided and unguided lumbar puncture are always coded identically regardless of whether imaging guidance was used');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aa90271d-67fc-4ba7-9827-e43b00553c85', 'f7f645de-6549-4cea-a3cf-15a345f98d91', 2, 'Fluoroscopic guidance for lumbar puncture has no distinct coding relevance under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3f416292-6caa-43a1-a8a2-bc6e42a15219', 'f7f645de-6549-4cea-a3cf-15a345f98d91', 3, 'Lumbar puncture guidance coding depends solely on the patient''s body habitus, not whether guidance was actually used');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dc51b891-05ed-4afd-8e40-21a263f8e322', '96afa3a0-3447-4ae2-9e34-d0477f99946b', 0, 'A fluoroscopic (rather than MRI-based) arthrogram may have its own distinct code/combination reflecting the different subsequent imaging modality (fluoroscopy/plain film vs. MRI) used after the joint injection, requiring the same combined-versus-component and modality-specificity analysis already established');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c53c4884-f42e-40fa-a7a2-823cf0a19e0c', '96afa3a0-3447-4ae2-9e34-d0477f99946b', 1, 'Fluoroscopic and MRI arthrography are coded identically regardless of which subsequent imaging modality is used');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('82aa92c7-ff3c-4705-b434-bc43e48e70ac', '96afa3a0-3447-4ae2-9e34-d0477f99946b', 2, 'Fluoroscopic arthrography has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('70c52f1c-8285-43b9-833d-3e0fa255e01f', '96afa3a0-3447-4ae2-9e34-d0477f99946b', 3, 'Arthrogram coding depends solely on which joint is injected, not the subsequent imaging modality used');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('87e4dc7b-b728-4abe-bdcb-c17d66e79aad', 'f3a92074-1a08-439a-a56a-51b0c9e8a585', 0, 'Plain-film myelography and CT myelography represent different subsequent imaging modality choices following the same general myelographic contrast injection technique, each potentially mapping to different specific codes — reinforcing the modality-specificity theme already established for myelography generally');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d08d9cfb-9348-4407-87b2-f2567b0f9f3c', 'f3a92074-1a08-439a-a56a-51b0c9e8a585', 1, 'Plain-film and CT myelography are always coded identically regardless of the subsequent imaging modality used');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('38fc2304-39f3-466a-8b55-8da942504561', 'f3a92074-1a08-439a-a56a-51b0c9e8a585', 2, 'Plain-film myelography has no distinct CPT code and must use an unlisted radiology procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2c527092-59a6-4484-a2ba-ef3f68b548de', 'f3a92074-1a08-439a-a56a-51b0c9e8a585', 3, 'Myelography coding depends solely on the contrast volume injected, not the subsequent imaging modality');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('860c3069-ec6b-40dc-aecb-52af4f0db485', '0e0b8d28-d5c2-4276-ba02-b53c4e7395c5', 0, 'The procedure report should specify both the guidance modality actually used (if any) and whether that specific procedure code already includes guidance in its own descriptor or requires a separate guidance code, since assuming either bundling or separate-reportability without checking the specific code risks either under-reporting (missing a legitimately separate code) or over-reporting (double-billing bundled guidance)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a4b27e78-c55c-4d60-ab8e-bd7cf32604be', '0e0b8d28-d5c2-4276-ba02-b53c4e7395c5', 1, 'No documentation of guidance modality is needed since all image-guided procedures are coded identically regardless of whether guidance was used');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e6301570-270f-4496-9736-7f9c49003e0c', '0e0b8d28-d5c2-4276-ba02-b53c4e7395c5', 2, 'Guidance documentation is relevant only for research purposes, never routine clinical coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e726d4bf-5bd2-4cf9-a99e-423f13c2e629', '0e0b8d28-d5c2-4276-ba02-b53c4e7395c5', 3, 'Assuming guidance is always separately billable (without checking the specific code) is the safest, most accurate default approach');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2bcea9a4-09d6-4afe-a3d0-3adc1497e35d', '2b73e7de-7aeb-4f63-b3ce-0538bbd67f7e', 0, 'Weight-bearing status may be a relevant, documented clinical detail affecting which specific code applies for certain joint X-ray studies, reflecting the recurring theme that specific documented imaging protocol details (not just body part and view count) can determine correct code selection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0e3749f4-9013-49ae-8f89-6aeff1f1ea95', '2b73e7de-7aeb-4f63-b3ce-0538bbd67f7e', 1, 'Weight-bearing status has no bearing on X-ray code selection under any circumstance, only body part and view count matter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8d701c61-b3ec-4aaa-800c-ad945a1a8e6f', '2b73e7de-7aeb-4f63-b3ce-0538bbd67f7e', 2, 'Weight-bearing and non-weight-bearing views of the same joint are always coded using a single universal code with no protocol distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9093a229-38b0-4693-8f4f-a04d26e606e0', '2b73e7de-7aeb-4f63-b3ce-0538bbd67f7e', 3, 'Weight-bearing status is relevant only to physical therapy documentation, never to radiology coding');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('45747210-7444-4a0c-b11c-5ed23a9db8a5', '4c98cb51-475c-436a-b57c-4b0efc7b6692', 0, 'Accurate radiology coding consistently requires looking beyond the basic ''what body part, what modality'' question to the SPECIFIC protocol/technique details actually documented and performed, since CPT radiology codes are frequently structured around these finer protocol distinctions rather than a single code per body-part-and-modality combination');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d43683ed-3d11-45fa-976a-a1dbc786d5b0', '4c98cb51-475c-436a-b57c-4b0efc7b6692', 1, 'Radiology coding depends solely on body part and modality, with protocol/technique details being irrelevant administrative trivia');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b476ccf7-8c02-4bef-af05-627a9c765028', '4c98cb51-475c-436a-b57c-4b0efc7b6692', 2, 'Protocol-specificity concerns apply only to advanced imaging (MRI/CT/PET), never to plain-film radiography');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('95acff49-2c44-4eed-972f-c977cce3ad9c', '4c98cb51-475c-436a-b57c-4b0efc7b6692', 3, 'Each protocol-specificity example (contrast, function, guidance, weight-bearing) represents an isolated, unrelated coding quirk with no common underlying principle');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d2c5ca65-763a-4512-a4a5-bab914ff658c', '086026a2-6612-41a0-a770-6c69155ac99f', 0, 'Systematically identify: (1) the imaging modality, (2) the specific body part/anatomic region, (3) any contrast protocol used, (4) whether the study serves a specialized purpose beyond basic anatomic imaging (angiographic, functional, screening-vs-diagnostic), (5) whether imaging guidance for another procedure is bundled or separate, and (6) any other documented protocol-specific details (view count, weight-bearing status) — then match all of these specifics together to the single code descriptor that accurately reflects the complete, actual study performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d1869919-17a9-4e33-9e02-b4e24d1af26f', '086026a2-6612-41a0-a770-6c69155ac99f', 1, 'Radiology coding is fundamentally simple, requiring only identification of body part and modality with no further analysis needed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4fff60fe-6d20-440f-a2d8-066df3a5dafa', '086026a2-6612-41a0-a770-6c69155ac99f', 2, 'Each of the six analytical factors identified operates in isolation with no need to consider them together when selecting a single code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('683742cd-ba20-4403-b034-93d62c4b59c4', '086026a2-6612-41a0-a770-6c69155ac99f', 3, 'Rely on the requesting physician''s order description alone, without confirming it matches the study actually performed and documented by the imaging department');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6aebfd83-5818-4300-bba3-71495378bf5c', '3df4bd79-ed6a-4002-90b5-b8a88fefe27b', 0, 'Allergen-specific IgE blood testing has its own specific laboratory code(s), distinct from skin testing (a different technique performed in a different setting/manner), each allergen typically coded per the number of specific allergens tested, reflecting a units-based structure similar to other multi-analyte laboratory testing already discussed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('23682286-33f8-4f41-b25b-524cc1d4e6b4', '3df4bd79-ed6a-4002-90b5-b8a88fefe27b', 1, 'Blood-based IgE testing and skin prick testing are coded identically since both test for allergies');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('35d46a37-5c3f-4820-a522-374e558c5fc1', '3df4bd79-ed6a-4002-90b5-b8a88fefe27b', 2, 'Allergen-specific IgE testing has no distinct CPT code and must use an unlisted laboratory procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3f99e4dc-56af-4eb0-9180-3960e36043dc', '3df4bd79-ed6a-4002-90b5-b8a88fefe27b', 3, 'IgE allergy testing is coded using a single flat code regardless of how many specific allergens are tested');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9039823a-62ba-4d7c-bf67-fc2a7ae5ae24', '315e28de-421b-4de6-9602-a805d5b2c25c', 0, 'Total IgE (a single overall measurement) and allergen-specific IgE (testing for reactivity to particular allergens) are distinct, separately coded tests measuring different things, even though both involve the IgE antibody class');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e617a5c1-1f9a-4da1-938d-6bcd064d6330', '315e28de-421b-4de6-9602-a805d5b2c25c', 1, 'Total and allergen-specific IgE are coded identically since both measure IgE');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f2148002-3e51-42d0-8f94-797f5610508d', '315e28de-421b-4de6-9602-a805d5b2c25c', 2, 'Total IgE has no distinct CPT code and must use an unlisted laboratory procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('788da29c-18f0-4dcf-9473-3b3e00af737f', '315e28de-421b-4de6-9602-a805d5b2c25c', 3, 'Total IgE testing is coded using the same code as a complete blood count');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9c4ac98b-07e6-4fcb-8b0e-7dc29110c7be', 'b2a80e33-f89c-406b-9f87-0fe25d00745d', 0, 'If a defined immunoglobulin panel code exists and ALL of its specific component tests (each immunoglobulin class) were performed, the panel code is reported; if only a subset was ordered/performed, only the individual component code(s) actually performed are reported — reinforcing the panel-completeness principle already established generally');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('35e051f4-0016-4bf2-82a4-58e713fe62f9', 'b2a80e33-f89c-406b-9f87-0fe25d00745d', 1, 'The immunoglobulin panel code may be reported regardless of how many of its component immunoglobulin classes were actually measured');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e336c459-c6b9-4234-b12b-3615ae776b9a', 'b2a80e33-f89c-406b-9f87-0fe25d00745d', 2, 'Immunoglobulin panel components can never be individually coded; only the full panel code exists');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bd6c05d3-31b6-4c6c-929e-29becb2102b9', 'b2a80e33-f89c-406b-9f87-0fe25d00745d', 3, 'Immunoglobulin panel coding depends solely on the patient''s age, not which specific components were tested');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('34e29f99-6428-470a-bd0d-b3ef7674a855', 'c560d5c8-ced1-40a1-9bc5-e49a00fe59b3', 0, 'Autoimmune antibody tests (like ANA) are structurally and clinically distinct from allergy-specific IgE tests, each having their own specific codes reflecting genuinely different antibody classes/clinical purposes (autoimmune disease evaluation vs. allergic reactivity), despite both being ''antibody'' tests in a broad sense');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6af9289e-e5b2-4ed1-b2b2-392192104d03', 'c560d5c8-ced1-40a1-9bc5-e49a00fe59b3', 1, 'ANA and allergy-specific IgE testing are coded identically since both are antibody tests');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ccceab8d-2b53-44d6-be0f-fe70b43d3026', 'c560d5c8-ced1-40a1-9bc5-e49a00fe59b3', 2, 'ANA testing has no distinct CPT code and must use an unlisted laboratory procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0840031b-d6e8-4651-8bf4-7e726f5e7b53', 'c560d5c8-ced1-40a1-9bc5-e49a00fe59b3', 3, 'Autoimmune antibody testing is coded using the same code as a complete blood count');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eded115b-5d6b-4b25-80da-78a83b9f7f06', '7f0bab2d-4e5c-4c70-91ed-dfc5d79f3994', 0, 'The reflex subtype-specific testing may be separately reportable, since — consistent with the reflex-testing principle already established generally — this represents a genuinely distinct, additional laboratory test triggered by the initial result, not something automatically bundled into the initial ANA code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f38bf16d-f545-42c8-b95e-6bb6f5cd3710', '7f0bab2d-4e5c-4c70-91ed-dfc5d79f3994', 1, 'Reflex autoimmune subtype testing is always included in the initial ANA code with no separate reporting ever possible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('80152b88-7507-47ac-8320-4f77f320f53f', '7f0bab2d-4e5c-4c70-91ed-dfc5d79f3994', 2, 'Reflex testing applies only to cytology (already discussed) and toxicology, never to autoimmune antibody testing');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6deb4c6a-883b-432c-bde7-f9a5f8b33d8a', '7f0bab2d-4e5c-4c70-91ed-dfc5d79f3994', 3, 'ANA reflex testing has no distinct CPT code regardless of which specific subtype antibodies are tested');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('25dd3d10-8f78-4710-8053-f407206f1028', '7275aad6-2564-4320-b64e-7fc32c51e6a7', 0, 'Complement levels (C3, C4) and immunoglobulin levels (IgG, IgA, IgM, IgE) are distinct components of the broader immune system, each with their own specific, separately coded tests, reflecting genuinely different immunologic parameters being measured');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('42db1dd1-95a2-494f-b008-8036f68c0788', '7275aad6-2564-4320-b64e-7fc32c51e6a7', 1, 'Complement and immunoglobulin testing are coded identically since both relate to immune function');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fb76b1e7-d360-4747-9df2-12948f90e6b6', '7275aad6-2564-4320-b64e-7fc32c51e6a7', 2, 'Complement level testing has no distinct CPT code and must use an unlisted laboratory procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7f86e1de-718c-4239-9145-bb8d5ccd1c4c', '7275aad6-2564-4320-b64e-7fc32c51e6a7', 3, 'C3 and C4 are always combined into a single code with no separate reporting option for each component');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('517ee221-4457-4729-a914-2086dc32195c', 'e5c6ab08-6c3d-4475-9dc6-67d3fc64bffc', 0, 'HLA typing has its own specific, specialized code(s) distinct from general immunology/autoimmune antibody testing, reflecting its own specific clinical purpose (transplant/tissue compatibility matching) and specialized testing methodology');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bc412c28-8d93-4cd2-8406-4b0500216fcc', 'e5c6ab08-6c3d-4475-9dc6-67d3fc64bffc', 1, 'HLA typing is coded identically to a routine immunoglobulin panel');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d369d86d-f5ef-4788-bd34-f4c56258d3a6', 'e5c6ab08-6c3d-4475-9dc6-67d3fc64bffc', 2, 'HLA typing has no distinct CPT code and must use an unlisted laboratory procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('94f08faf-b0fb-4027-95e1-0945a5aafcbe', 'e5c6ab08-6c3d-4475-9dc6-67d3fc64bffc', 3, 'HLA typing coding depends solely on the specific organ being transplanted, not the actual testing methodology used');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f946654a-2f7c-4e5d-9492-131527a826df', 'c62d66b6-e749-4a0e-b4f8-f07f816681fd', 0, 'The laboratory requisition/report should specify exactly which specific analytes/allergens/antibody subtypes were actually tested, since — consistent with the documentation-specificity theme established across panels, reflex testing, toxicology, and endocrine testing throughout this content — this specific detail (not a general category label like ''immunology workup'') determines correct code selection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('39b04f04-7c03-41b3-abb1-647dd5260f64', 'c62d66b6-e749-4a0e-b4f8-f07f816681fd', 1, 'General documentation of ''immunology testing performed'' is sufficient regardless of which specific analytes were actually tested');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('40c798fa-639b-47ed-bc27-0487dfbe7ead', 'c62d66b6-e749-4a0e-b4f8-f07f816681fd', 2, 'Immunology/allergy testing follows an entirely different documentation standard from the panel/reflex/toxicology/endocrine principles already established elsewhere in this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6a3ba154-8616-4c58-a6a3-88fbef28e215', 'c62d66b6-e749-4a0e-b4f8-f07f816681fd', 3, 'Specific analyte documentation is relevant only for research-context immunology testing, never routine clinical allergy/autoimmune evaluation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0ac55fd7-9074-44f9-ad31-7017d779bdde', '4c747388-d483-4883-8792-1817df440bdc', 0, 'Similar to the medical-necessity concerns already established for excessive/undifferentiated drug testing, ensuring allergy panel testing is genuinely clinically targeted (based on specific suspected allergens from patient history) rather than routine, broad panels ordered regardless of individual clinical indication is a reasonable compliance/medical-necessity consideration');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ccc90295-f087-46b1-a050-17a5327a9359', '4c747388-d483-4883-8792-1817df440bdc', 1, 'Allergy testing carries no distinct medical-necessity or compliance considerations from any other laboratory test category');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('05fb5167-e893-4b3c-bbf4-7d8a982ed8b5', '4c747388-d483-4883-8792-1817df440bdc', 2, 'Broad, non-targeted allergy panels should always be ordered for every patient to ensure no allergen is missed, regardless of cost or clinical indication');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2b2655d3-00c6-4d9c-b7a8-26f6aa12c573', '4c747388-d483-4883-8792-1817df440bdc', 3, 'Medical necessity concerns apply only to toxicology testing, never to allergy/immunology testing');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0bf21e1f-607b-427b-a85b-1025345d435e', '8d126407-6566-438b-9830-f2cf53e44b87', 0, 'Across every laboratory subsection examined in this series, accurate coding consistently depends on identifying the SPECIFIC analyte(s), methodology, and testing structure actually performed and documented — verified against each code''s own defined scope (panel component lists, reflex triggers, presumptive-vs-definitive methodology, timed-protocol structures) — rather than relying on broad category labels, and genuine medical necessity (not routine/reflexive testing patterns) should drive testing decisions across every laboratory subsection, not just the specific examples where this was first raised');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a36b3729-b1e5-4117-a06b-6c546288ecf0', '8d126407-6566-438b-9830-f2cf53e44b87', 1, 'Each Pathology & Laboratory subsection requires an entirely separate, unrelated analytical approach with no common principles connecting them');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fed9faa9-45ec-4180-b950-47495883f9b1', '8d126407-6566-438b-9830-f2cf53e44b87', 2, 'Laboratory coding is fundamentally about matching the ordering physician''s diagnosis code to the broadest available test code, without regard to the specific test actually performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8d465a0c-327a-41a8-8abe-208d701fa20e', '8d126407-6566-438b-9830-f2cf53e44b87', 3, 'Medical necessity and documentation-specificity concerns apply only to certain ''high-risk'' laboratory subsections (toxicology, allergy) with no relevance to routine chemistry or hematology testing');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f13f7952-921a-44f8-b7be-29d272d5c9af', 'd969ec2a-a618-4905-94c5-97b42e73f8b7', 0, 'Individual psychotherapy codes are generally time-tiered (distinct codes for approximately 30, 45, and 60-minute sessions), meaning the actual documented session duration directly determines correct code selection, consistent with the time-documentation-specificity theme established throughout this content''s Medicine-section coverage');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('703fccd4-e4b7-4241-9738-36684f1ce455', 'd969ec2a-a618-4905-94c5-97b42e73f8b7', 1, 'A single universal psychotherapy code applies regardless of session duration');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c9702a96-a442-46db-8a51-d37264c16dee', 'd969ec2a-a618-4905-94c5-97b42e73f8b7', 2, 'Only 60-minute psychotherapy sessions have a CPT code; shorter sessions are never separately billable');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2011ad77-bb2b-437d-af0b-6d2cb58aa444', 'd969ec2a-a618-4905-94c5-97b42e73f8b7', 3, 'Psychotherapy session duration is relevant only to reimbursement amount, not to which specific code is selected');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dc45a09f-b7db-42e8-a11b-6f439de67189', 'f08f8a0d-094f-419b-8f1e-91f379559eb6', 0, 'These represent distinct codes reflecting the different participant structure (patient present and participating vs. family/caregiver session addressing the patient''s condition without the patient there), consistent with the general service-structure/participant-specificity theme established throughout this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b7d6fd2d-dfa0-4407-af4e-116f6e5810b8', 'f08f8a0d-094f-419b-8f1e-91f379559eb6', 1, 'Family therapy with and without the patient present is always coded identically regardless of participant structure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7e9e663e-d988-46d0-9f48-a829da91299e', 'f08f8a0d-094f-419b-8f1e-91f379559eb6', 2, 'Family psychotherapy without the patient present has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9eabc9ba-46ab-4385-bab3-d03fb8324eb6', 'f08f8a0d-094f-419b-8f1e-91f379559eb6', 3, 'The choice between these codes depends solely on session duration, not whether the patient is actually present');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ba75c1dd-8876-4f7b-b8cc-b4e166c20186', '22e3aa0a-a752-44af-ac2b-f108c27872a6', 0, 'Group psychotherapy has its own specific code, distinct from both individual psychotherapy (one-on-one) and general group medical visits (which address general medical, not specifically psychotherapeutic, content), reflecting genuinely different service structures and clinical content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d95a53a6-c8f4-4b72-93d2-35e80252eb19', '22e3aa0a-a752-44af-ac2b-f108c27872a6', 1, 'Group psychotherapy is coded identically to individual psychotherapy since both are ''psychotherapy''');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2f599071-e0c4-4a71-9c20-bca6af9810f7', '22e3aa0a-a752-44af-ac2b-f108c27872a6', 2, 'Group psychotherapy has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6ad2bfee-c501-49e1-8695-580d85db9a79', '22e3aa0a-a752-44af-ac2b-f108c27872a6', 3, 'Group psychotherapy is coded using the same code as a general group medical visit regardless of the specific therapeutic content/structure');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('462e497c-5fc9-49bc-9b11-66e55f7652f2', 'e3dd16e6-f5e8-4314-ba6b-c4eec5a35ba5', 0, 'Psychotherapy for crisis has its own specific, time-based code(s) (with a base time threshold and add-on codes for additional time), reflecting the distinct, urgent nature of this service compared to routine, scheduled psychotherapy sessions — mirroring the general pattern of specialized/urgent services having their own distinct code structure already seen for critical care');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6d449269-c618-4422-838a-42211cf0ac1d', 'e3dd16e6-f5e8-4314-ba6b-c4eec5a35ba5', 1, 'Crisis psychotherapy is coded identically to routine scheduled psychotherapy regardless of the urgent/crisis nature of the encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3afe98e7-fc5a-432c-a94e-28f33b44f8d9', 'e3dd16e6-f5e8-4314-ba6b-c4eec5a35ba5', 2, 'Crisis psychotherapy has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d4b52bdd-73e9-439e-abf6-66607c9179d9', 'e3dd16e6-f5e8-4314-ba6b-c4eec5a35ba5', 3, 'Crisis psychotherapy coding depends solely on the specific crisis diagnosis code used, not the actual time-based service structure');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('55ac462e-35b9-40b4-897e-5e8955fb977c', '58badb92-5faf-49cf-8c01-4a9c1aaf91b6', 0, 'Documentation should reflect the actual total time spent face-to-face with the patient and/or family managing the crisis (not simply that "a crisis occurred"), consistent with the time-documentation principle already established for other time-based code families, since the base and add-on crisis codes depend on this documented duration');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('00588f2c-0c51-4524-ad9b-42cbaaab581f', '58badb92-5faf-49cf-8c01-4a9c1aaf91b6', 1, 'No time documentation is needed since crisis psychotherapy is billed as a flat fee regardless of actual time spent');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('187781bd-d562-463b-a373-70de604b2842', '58badb92-5faf-49cf-8c01-4a9c1aaf91b6', 2, 'Only the crisis diagnosis needs to be documented; time spent managing the crisis is not relevant to code selection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1c7ed4a2-9e18-498f-b186-5497628790d1', '58badb92-5faf-49cf-8c01-4a9c1aaf91b6', 3, 'Crisis psychotherapy time documentation requirements are unrelated to any other time-based code family''s documentation principles');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fd9e7f2b-9376-46d0-9c3d-4f49429dd3f7', 'ee3e8910-cdc6-49e8-8cf1-fcd2fb8f1e1f', 0, 'The same underlying psychotherapy codes (individual, family, group, crisis) generally apply whether delivered in-person or via telehealth, with an appropriate telehealth modality modifier/place-of-service indicator appended, mirroring the general telehealth-modifier concept already established for E/M services');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('580c5745-aa8a-4863-a4d1-fdc28a08bf8a', 'ee3e8910-cdc6-49e8-8cf1-fcd2fb8f1e1f', 1, 'Telehealth psychotherapy uses an entirely separate, unrelated code set from in-person psychotherapy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eabd8b42-3bdb-4b29-a080-a1a611c21894', 'ee3e8910-cdc6-49e8-8cf1-fcd2fb8f1e1f', 2, 'Psychotherapy can never be delivered or coded as a telehealth service under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c3098a68-595d-497a-9b88-2c16c8c7b4b4', 'ee3e8910-cdc6-49e8-8cf1-fcd2fb8f1e1f', 3, 'Telehealth psychotherapy is always billed at the lowest available psychotherapy code level regardless of actual session content/duration');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('821b85b6-4ab2-4d2e-9e3d-e919f30141a6', 'a99dcb9a-63d0-4ccc-a366-7203f9446eb1', 0, 'This is the concrete application of the Paper 1 add-on psychotherapy code concept — the E/M code (based on its own time/MDM) is reported together with the add-on psychotherapy code (reflecting the additional psychotherapy time/content provided in the same visit), rather than requiring these to be billed as two entirely separate encounters');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a92ce8c8-ac07-472e-82e4-c450ae5313f2', 'a99dcb9a-63d0-4ccc-a366-7203f9446eb1', 1, 'Medication management and psychotherapy can never both be provided or coded during the same single visit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('76c1b64b-b712-4b06-a769-53f12a4097c4', 'a99dcb9a-63d0-4ccc-a366-7203f9446eb1', 2, 'Only the psychotherapy add-on code is ever billed, with the E/M service considered automatically bundled into it with no separate E/M code reported');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f86cd7a2-be1a-4065-b04f-e85fc7e07fb1', 'a99dcb9a-63d0-4ccc-a366-7203f9446eb1', 3, 'This combination requires an entirely different, unrelated code structure from the add-on psychotherapy codes already discussed in Paper 1');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('60ceb9ee-6551-42da-a8f4-dc8879dc459c', '2c7636f1-1cb1-4b5f-9e4b-d787b1acfeb7', 0, 'Psychological/neuropsychological testing has its own specific, typically time-based code family, distinct from psychotherapy codes, reflecting a genuinely different service type (standardized testing administration/scoring/interpretation) from ongoing therapeutic treatment');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b2557147-6767-4ebf-ad12-0022f6891041', '2c7636f1-1cb1-4b5f-9e4b-d787b1acfeb7', 1, 'Psychological testing is coded identically to individual psychotherapy since both are behavioral health services');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6ad8eae8-bcbf-4863-95f6-eaa38c99e6a8', '2c7636f1-1cb1-4b5f-9e4b-d787b1acfeb7', 2, 'Psychological testing has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('76a81b9f-f6eb-41f3-8cf6-67181866dbf4', '2c7636f1-1cb1-4b5f-9e4b-d787b1acfeb7', 3, 'Psychological testing coding depends solely on which specific test instrument is used, with no time-based component ever relevant');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0badebb6-fbe3-4573-9bba-abaf1c097d7c', '31155cc4-4aad-4890-aee6-afd619ef711f', 0, 'Apply the same disciplined analytical approach already established throughout this content''s Medicine-section coverage — identify the specific service type (diagnostic evaluation vs. ongoing psychotherapy vs. crisis intervention vs. testing), participant structure (individual/family-with-patient/family-without-patient/group), actual documented time for time-based codes, and delivery modality — then match to the correct specific code, rather than treating ''behavioral health'' as a single undifferentiated billing category');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5ab2bada-159d-44b9-adc1-15b5f3c9d97f', '31155cc4-4aad-4890-aee6-afd619ef711f', 1, 'All behavioral health services are billed using a single generic ''psychotherapy'' code regardless of service type, participant structure, or time');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('00a8790a-5018-43a9-a0b0-e74fd02fd78c', '31155cc4-4aad-4890-aee6-afd619ef711f', 2, 'Behavioral health coding requires an entirely separate analytical framework unrelated to the broader Medicine-section principles already established');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a293768f-3411-4ce8-96cd-174479ad8797', '31155cc4-4aad-4890-aee6-afd619ef711f', 3, 'Rely on the behavioral health diagnosis code alone to determine which specific psychiatric/psychological CPT code applies, without confirming the actual service type/structure performed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4a3d09c3-b1dc-4ba0-9e61-531aba00b89f', 'a8e04613-e21d-47e6-a1f1-2ba85d1ddacb', 0, 'Despite the Medicine section''s genuinely wide-ranging scope spanning many unrelated-seeming specialties, accurate coding consistently depends on the same underlying discipline — identifying the SPECIFIC service structure actually documented (product-plus-administration, timed-versus-untimed, evaluation-versus-ongoing-treatment, individual-versus-group-versus-family, and specific technique/methodology within broad categories) — rather than assuming a single billing structure applies uniformly across this diverse section');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9fbc5a99-dee3-4a2c-91ff-b9388cdb9e75', 'a8e04613-e21d-47e6-a1f1-2ba85d1ddacb', 1, 'The Medicine section is too diverse to have any common underlying coding principles, requiring an entirely separate memorized approach for each specialty');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1d8f8d99-7948-4438-804b-d246e42b6012', 'a8e04613-e21d-47e6-a1f1-2ba85d1ddacb', 2, 'Medicine-section coding is fundamentally simpler than Surgery or Radiology-section coding and requires no systematic analytical approach');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('98218346-5858-457a-8f73-e8928578d698', 'a8e04613-e21d-47e6-a1f1-2ba85d1ddacb', 3, 'Only a small number of ''common'' Medicine-section codes have real-world relevance; the more specialized service types covered in this content are rarely encountered in practice');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2bcfccd2-8cfa-4ba8-a695-e28db42d1e23', '78b52cc7-bfce-408b-89a6-c370256b3d91', 0, 'A claim-line MUE edit checks whether the units on a SINGLE claim line exceed the MUE value, while a date-of-service edit sums units for that code across ALL claim lines for that patient on that date (potentially across multiple claims) before comparing to the MUE value — meaning a code could pass a claim-line check but still fail a date-of-service check if split across multiple lines/claims');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e43b9f7e-2b4d-4408-8842-02dab7622c05', '78b52cc7-bfce-408b-89a6-c370256b3d91', 1, 'Claim-line and date-of-service MUE edits are identical concepts with no practical distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5883dd15-c903-4c6f-b124-f92c4c826a9f', '78b52cc7-bfce-408b-89a6-c370256b3d91', 2, 'Date-of-service MUE edits apply only to laboratory codes, never procedural codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a6b7d75c-3906-4327-ae5d-64681fe849dd', '78b52cc7-bfce-408b-89a6-c370256b3d91', 3, 'MUE edits never consider units across multiple claim lines under any adjudication approach');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ecf1eaef-7773-47bb-8d07-2cb2efa9aa6a', '9cd6de85-4490-4684-ae01-531c3a206b4f', 0, 'Attempting to split units across multiple claim lines specifically to avoid triggering an MUE edit, for a code that is actually adjudicated at the date-of-service level, would not achieve the intended effect and could itself represent a concerning billing pattern rather than a legitimate coding practice');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e23e1619-bb62-45bb-bbc3-11d879d258bd', '9cd6de85-4490-4684-ae01-531c3a206b4f', 1, 'This distinction has no practical or compliance relevance to actual billing practice');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d2848fa9-d908-4a82-8257-8483e0e31ef8', '9cd6de85-4490-4684-ae01-531c3a206b4f', 2, 'Splitting units across multiple lines always successfully avoids MUE edits regardless of a code''s specific adjudication methodology');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5c474a9d-b2c1-40e7-b6b0-a4834cc439f9', '9cd6de85-4490-4684-ae01-531c3a206b4f', 3, 'MUE adjudication methodology is relevant only to CMS internal system design, with zero external biller-facing relevance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9c0e8d1b-5432-4304-99f3-a0d05be1e752', 'e38e0fcd-4c60-48f4-b4f6-5b81ac4a4e59', 0, 'Reviewing the documentation to confirm the units are genuinely, accurately supported, and then pursuing the payer''s defined appeal/reconsideration process (since MUEs are designed to catch implausible/erroneous unit counts, not to serve as an absolute clinical cap that can never legitimately be exceeded in a genuinely unusual, well-documented case) rather than either abandoning a legitimate claim or attempting to circumvent the edit through improper means (like line-splitting)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fc4dd2c0-e9c6-43d6-a5e9-e901f5308cd0', 'e38e0fcd-4c60-48f4-b4f6-5b81ac4a4e59', 1, 'MUE denials can never be appealed or reconsidered under any circumstance, regardless of documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a04ecc77-fbd4-4661-9d6c-7efad4566307', 'e38e0fcd-4c60-48f4-b4f6-5b81ac4a4e59', 2, 'The correct response is always to reduce the billed units to match the MUE value, regardless of what was actually and legitimately performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9f1ec256-febe-4a53-a381-80e43724f761', 'e38e0fcd-4c60-48f4-b4f6-5b81ac4a4e59', 3, 'MUE edits are absolute clinical caps that no genuinely documented case could ever legitimately exceed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('63adc931-a297-4a92-8fef-e9f12ec5d1d4', '25a6bcd0-f035-41ac-91a9-956de79240f1', 0, 'MUEs address the maximum plausible UNITS of a single code for one patient on one date, while PTP edits address whether two DIFFERENT codes may be reported together for the same patient on the same date — two distinct edit types addressing different potential billing-accuracy issues (excessive units vs. improper code-pair combinations) within the same overall NCCI program');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('55349071-ee9a-4633-9898-8cad1482b2cf', '25a6bcd0-f035-41ac-91a9-956de79240f1', 1, 'MUEs and PTP edits are the same type of edit, just using different terminology');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1b41e650-85be-45e9-a967-98299731a4cd', '25a6bcd0-f035-41ac-91a9-956de79240f1', 2, 'PTP edits address unit limits, while MUEs address code-pair bundling — the reverse of their actual definitions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('90338035-76fe-4e3e-9877-fff6a55aacd5', '25a6bcd0-f035-41ac-91a9-956de79240f1', 3, 'MUEs and PTP edits can never both apply to the same claim');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2a814bdb-0a82-439f-887e-e302758039e1', 'f8cb2aab-7321-4e4d-bc6a-e33836fc0a2a', 0, 'Given that MUEs and PTP edits address different underlying issues (unit plausibility vs. code-pair combination), a denial''s root cause should be correctly identified (which edit type actually triggered it) before determining the appropriate response — applying a PTP-bypass-modifier response (like 59) to an MUE-triggered denial wouldn''t address the actual underlying issue, since MUEs generally aren''t resolved via that type of modifier the way certain PTP edits are');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('46215ffa-16d2-4f32-819b-8cd11d0e91e9', 'f8cb2aab-7321-4e4d-bc6a-e33836fc0a2a', 1, 'The same corrective response (applying modifier 59) is always appropriate regardless of whether an MUE or PTP edit triggered the denial');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d813f1ad-ddda-4811-a282-495f19d845a8', 'f8cb2aab-7321-4e4d-bc6a-e33836fc0a2a', 2, 'MUE and PTP denials are visually and procedurally identical with no way to distinguish which edit type actually caused a given denial');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ac780318-bf9b-4c9f-a0c6-69e668e511e3', 'f8cb2aab-7321-4e4d-bc6a-e33836fc0a2a', 3, 'Only PTP edits ever result in claim denials; MUE edits have no denial/payment consequence');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ee7a6f42-65ff-47ae-bfe2-8a9f34d073d6', '655ed56e-e2a6-40b7-88db-5c3ef9f4de09', 0, 'This represents a genuine, documented technical interaction between modifiers and MUE values that CMS''s MUE program is designed to account for through specific guidance/adjudication logic for bilateral-modifier scenarios — reinforcing that modifier use (50, in this case) and MUE unit-counting are related but distinct concepts requiring correct understanding of how they interact for the specific code involved');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e56e6ad2-0426-4967-92c6-8a897e10cccc', '655ed56e-e2a6-40b7-88db-5c3ef9f4de09', 1, 'Bilateral procedures using modifier 50 are always automatically exempt from any MUE consideration regardless of the specific code involved');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f1aef82b-60b6-4667-90bd-d3bf05ad5432', '655ed56e-e2a6-40b7-88db-5c3ef9f4de09', 2, 'MUE values are never relevant to bilateral procedures under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cad0afa4-a59d-4514-b4cb-c8c1ce09d442', '655ed56e-e2a6-40b7-88db-5c3ef9f4de09', 3, 'Modifier 50 and MUE values have no interaction or relationship whatsoever, always evaluated in complete isolation from each other');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cce27356-390d-4ed8-bea4-14fa38c092fc', '33a834bc-2f3c-487a-9b7c-90295714e6f0', 0, 'Apply the same disciplined analytical approach already established throughout this content''s Modifiers & NCCI coverage — correctly identify which specific NCCI edit type (PTP code-pair, or MUE unit-count) is actually relevant to the scenario, understand that edit type''s own specific adjudication logic (claim-line vs. date-of-service for MUEs; modifier-bypass-eligibility for PTP), and respond based on genuine documentation support rather than reflexive modifier application or unit-splitting');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6153b453-7b2f-4d25-a5b3-f98522e0f05d', '33a834bc-2f3c-487a-9b7c-90295714e6f0', 1, 'MUE and PTP edits should always be addressed using the identical corrective approach (applying modifier 59) regardless of which edit type is actually involved');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('307417eb-550f-4b33-89da-4d804909ec66', '33a834bc-2f3c-487a-9b7c-90295714e6f0', 2, 'MUE-related scenarios require an entirely separate, unrelated analytical framework from the PTP-edit and modifier principles already established throughout this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b9fb6942-49ed-4360-aa15-2e273bfc756b', '33a834bc-2f3c-487a-9b7c-90295714e6f0', 3, 'The safest approach to any NCCI edit, MUE or PTP, is always to reduce billed units/codes to whatever the system will accept without complaint, regardless of what was actually documented and performed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0dd6047e-f383-424d-ba02-874194ac6313', 'fbc1f302-17ca-415d-b191-c69bb1f52979', 0, 'Given that MUE-related issues often stem from specific, identifiable causes (e.g., miscounting units, misunderstanding claim-line vs. date-of-service adjudication, or system configuration errors in how units are calculated/reported), targeted analysis of an organization''s own MUE-denial patterns can help identify and correct SPECIFIC systemic causes, complementing (not replacing) general coding-accuracy training');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('15fb27d6-950f-4280-89d2-8c3a0c3730a5', 'fbc1f302-17ca-415d-b191-c69bb1f52979', 1, 'MUE-related billing errors have no distinct root causes worth investigating separately from any other coding error');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e6e9a6a0-d723-4d49-9b60-2831a87e9cde', 'fbc1f302-17ca-415d-b191-c69bb1f52979', 2, 'MUE compliance training should be identical in content to general PTP-edit compliance training, with no MUE-specific content ever needed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0e448db4-a796-4b8f-a5ab-048a14455efa', 'fbc1f302-17ca-415d-b191-c69bb1f52979', 3, 'Analyzing an organization''s own MUE-denial patterns has no practical compliance-improvement value');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('422e2916-9092-43e1-92af-5a0f4e29e729', '74e3764b-8a07-4e1d-8805-f81e95e2087d', 0, 'Every mechanism examined throughout this series — modifiers, PTP edits, and MUE edits — exists to help ensure that what is billed accurately reflects what was genuinely, documentably performed, at a genuinely plausible/accurate scope (correct units, correct code combinations, correct circumstances) — and the recurring compliance risk across ALL of these mechanisms is the same: attempting to manipulate or route around them (via reflexive modifiers, unit-splitting, or unsupported bypass claims) rather than ensuring the underlying documentation and billing genuinely, accurately reflect reality');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('20151904-654a-492e-84dc-5c2132940460', '74e3764b-8a07-4e1d-8805-f81e95e2087d', 1, 'PTP edits, MUE edits, and modifiers are three entirely unrelated billing mechanisms with no common underlying purpose or shared compliance risk pattern');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('03ddec73-2353-4184-bbc9-4de74fb1519d', '74e3764b-8a07-4e1d-8805-f81e95e2087d', 2, 'The purpose of NCCI edits and modifiers is to maximize reimbursement for healthcare organizations, with compliance being a secondary, less important consideration');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9b3d0549-3486-4497-99b2-9add07c61a2a', '74e3764b-8a07-4e1d-8805-f81e95e2087d', 3, 'Only PTP edits carry genuine compliance significance; MUE edits and modifier usage are purely administrative/technical matters with no fraud/abuse relevance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d54db941-4676-4ab5-99b7-76fcfa6819b5', '4e8d82ea-66ac-4241-a8d7-853509334df1', 0, 'Accurate, compliant CPT coding across every section and specialty examined in this series depends on a consistent, transferable analytical discipline: identifying the SPECIFIC documented facts (service structure, technique/approach, participant roles, time, anatomic specificity, methodology, relatedness/timing) that distinguish superficially similar services from each other, and matching those specific facts to the single code (or code-plus-modifier combination) that most accurately reflects what was genuinely performed — with the corresponding, equally consistent compliance principle being that documentation should drive code selection, never the reverse (selecting a code first and then seeking to justify or manipulate documentation/modifiers to support it)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fc590bea-2a24-48a0-962f-786aa22a272d', '4e8d82ea-66ac-4241-a8d7-853509334df1', 1, 'CPT coding is fundamentally a matter of memorizing individual code numbers for each specific clinical scenario, with no transferable analytical principles connecting different sections or specialties');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('27e27049-b67c-4f9f-a42c-a9d2f69eaac0', '4e8d82ea-66ac-4241-a8d7-853509334df1', 2, 'Each of the seven CPT sections requires an entirely separate, unrelated approach to coding with no common underlying discipline connecting them');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9bd19499-f08c-4456-8625-58167f78c394', '4e8d82ea-66ac-4241-a8d7-853509334df1', 3, 'The primary goal of accurate CPT coding is maximizing reimbursement, with documentation-accuracy and compliance being secondary considerations subordinate to that primary financial goal');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
